(() => {
  const course = window.textbookCourses?.nativeRussian7;
  if (!course) return;

  const solutions = {
    6: {
      question: `Проанализируйте словарные статьи к словам «целина» и «стрелец». Назовите значения, появившиеся под влиянием исторических событий, и определите, всегда ли первым указывается исторически первоначальное значение.`,
      answer: `«Целина»: 1) никогда не паханная или давно не обрабатывавшаяся земля; 2) земли Казахстана, Урала, Сибири и Поволжья, массово осваивавшиеся в 1954–1960 годах; 3) место, куда никто не ходил и не ездил. Историческое событие создало второе значение и сочетания «освоение целины», «поехать на целину», «герои целины».\n«Стрелец»: 1) воин постоянного русского войска XVI–XVII веков; 2) человек, родившийся под знаком Стрельца. Историческим является первое значение; с ним связаны слова «стрельцы», «стрелецкий», сочетания «стрелецкая слобода», «стрелецкий бунт».\nПервым в словарной статье не обязательно стоит самое древнее значение: обычно порядок зависит от современного употребления и структуры конкретного словаря. Например, у слова «целина» исходное значение стоит первым, а у многозначных слов историческая последовательность может не совпадать со словарной.`,
      rule: `Словарная статья показывает современные значения слова, а историческое событие может породить новое значение или устойчивое сочетание.`,
    },
    7: {
      question: `Сравните толкования слов «фермер» и «ферма» в современном словаре и в словаре 20–30-х годов XX века. Объясните изменения значений и их причины.`,
      answer: `В словаре Д. Н. Ушакова фермер — арендатор или владелец фермы, а ферма во втором значении — частное сельскохозяйственное предприятие именно в капиталистических государствах. В современном словаре С. И. Ожегова и Н. Ю. Шведовой территориально-идеологическое ограничение снято: фермер — владелец или арендатор фермы, ферма — частное сельскохозяйственное предприятие на собственном или арендованном участке.\nВ советский период частное хозяйство было нехарактерно для страны, поэтому слова связывались преимущественно с зарубежной действительностью. С возвращением частного фермерства в России они вошли в активный запас и получили современное нейтральное значение.`,
      rule: `Изменение общественного устройства меняет круг обозначаемых реалий и словарные пометы.`,
    },
    8: {
      question: `Прочитайте фрагмент Н. М. Шанского «Родословная дворняжки». Определите значение слова «родословная» в заголовке, запишите словообразовательную цепочку к слову «дворняжка» и объясните, что история слова говорит о развитии языка.`,
      answer: `В заголовке слово «родословная» употреблено переносно и означает историю происхождения слова.\nСловообразовательная цепочка: двор → дворный → дворняга → дворняжка. Слово «дворняжка» возникло как ласкательно-пренебрежительное название дворовой собаки; суффикс -к- добавился к слову «дворняга».\nИстория слова показывает постепенность языковых изменений: от названия места образовался признак, затем название животного и его разговорная уменьшительная форма. Такие изменения отражают быт и отношение людей к обозначаемому предмету.`,
      rule: `Словообразовательная цепочка располагает однокоренные слова от производящего к производному.`,
    },
    9: {
      question: `Распределите слова по тематическим группам, определите внешний фактор их появления, разделите их на заимствованные и образованные в русском языке и покажите образование русских слов.`,
      answer: `Главный внешний фактор — научно-технический прогресс и появление новых машин, приборов и областей знания.\nТематические группы: транспорт — трактор, атомоход, звездолёт, вертолёт, велосипед, паровоз, акваланг, ледокол; наука и техника — кибернетика, бионика; музыка и кино — пианино, кинематограф, кино, клип; бытовая техника — электрочайник, пылесос, холодильник, кофеварка, кондиционер; запись и печать информации — видеомагнитофон, принтер.\nЗаимствованные: трактор, кибернетика, велосипед, пианино, кинематограф, бионика, кондиционер, акваланг, клип, принтер.\nОбразованные в русском языке: атом + о + ход, звезд + о + лёт, верт + о + лёт, пар + о + воз, электр + о + чайник, пыл + е + сос, холод + ильник, кофе + вар + к + а, лёд + о + кол, видео + магнитофон; «кино» возникло сокращением слова «кинематограф».`,
      rule: `Заимствованное слово пришло из другого языка, а русское производное создаётся сложением основ, суффиксацией или сокращением.`,
    },
    10: {
      question: `Определите, что объединяет слова в пяти группах, выполните словообразовательный анализ и установите язык происхождения основ.`,
      answer: `Все слова образованы в русском языке от основ, часть которых была заимствована. Группы разделены по языку происхождения основы.\n1) Английские основы: флот-ск-ий, теннис-н-ый, волейбол-н-ый, имидж-ев-ый.\n2) Старославянские основы: при-бреж-н-ый, без-глас-н-ый, злат-о-глав-ый, древес-н-ый.\n3) Греческие основы: граммат-ическ-ий, синтакс-ическ-ий, при-кроват-н-ый, свёколь-н-ый.\n4) Французские основы: гарнизон-н-ый, салон-н-ый, балкон-н-ый, батальон-н-ый.\n5) Немецкие основы: вахт-енн-ый, бутерброд-н-ый, фельдшер-ск-ий, бирж-ев-ый.\nИх появлению способствовали культурные и торговые контакты, войны, развитие науки, армии, флота, спорта и городского быта. Заимствованные основы подчинились русским правилам словообразования.`,
      rule: `Производное может быть русским по способу образования, даже если его производящая основа когда-то была заимствована.`,
    },
    11: {
      question: `Приведите примеры заимствованных слов и объясните, какие внешние факторы помогли им закрепиться в русском языке.`,
      answer: `Примеры: компьютер, интернет, сайт, файл — развитие цифровых технологий и международный обмен; футбол, хоккей, теннис — распространение международного спорта; кафе, меню, ресторан — влияние европейской городской культуры; йогурт, кофе, шоколад — торговля и появление новых продуктов; менеджер, маркетинг — развитие рыночной экономики; балет, опера — культурные контакты.\nСлова закрепились, потому что называли новые предметы, занятия и явления, для которых не было коротких привычных русских названий. После освоения они изменяются по правилам русского языка и образуют производные: компьютерный, футбольный, хоккеист, ресторанный.`,
      rule: `Внешние факторы языкового развития — контакты народов, торговля, культура, политика и научно-технические изменения.`,
    },
    12: {
      question: `Прочитайте отрывок Д. С. Лихачёва. Объясните выражение «литературный староболгарский язык», сформулируйте основные мысли и оцените влияние других языков на русский.`,
      answer: `«Литературный староболгарский язык» — это старославянский, то есть первый литературный язык славян, пришедший на Русь вместе с письменностью и христианскими книгами.\nОсновные мысли: 1) русский язык выделился из древнерусского языка восточных славян; 2) общение на огромной территории поддерживало его единство; 3) русский язык обогащался старославянскими, греческими, скандинавскими, тюркскими, финно-угорскими и западноевропейскими элементами; 4) заимствования не разрушили язык, а сделали его гибким и восприимчивым.\nД. С. Лихачёв оценивает это влияние положительно. Я согласен: язык сохраняет собственную грамматику и основной словарь, но получает названия новых явлений. Современные примеры — интернет, смартфон, блог, сканер; от них уже образованы русские слова «интернетный/интернет-магазин», «блогер», «сканировать».`,
      rule: `Основная мысль текста выражает авторскую оценку фактов, а тезисы кратко передают ход рассуждения.`,
    },
    13: {
      question: `Перепишите текст орфографического и пунктуационного практикума, раскрывая скобки, вставляя буквы и знаки препинания.`,
      answer: `Всё, что мы видим, слышим, чувствуем, всё, что мы знаем, всё отражено в словах, в сочетаниях, зашифровано в грамматических формах и категориях, осмыслено, но в тонких оттенках речи. В языке сосредоточен жизненный опыт прошлых поколений, и этот опыт постепенно обогащается, изменяется язык. Это чудо человеческой цивилизации — язык — можно понять только в действии. Только в поиске новой мысли, в рассуждении, в столкновении идей. Потому что язык — это достояние каждого из нас, всех говорящих на этом языке. Для меня одного или для тебя одного языка нет.\nРазвитие языка продолжается всё время, неустанно, ежечасно. Устаревают слова, «затухают» формы и меняются значения слов. «Усыхают» окончания, неожиданным рывком создаются новые части речи. Шлифуется предложение или искромётно создаётся неизвестное прежде сочетание слов... Каждый день, каждый час.`,
      rule: `Однородные придаточные и члены предложения разделяются запятыми; вставные пояснения и приложение могут выделяться тире.`,
    },
    14: {
      question: `Найдите в отрывках историзмы, объясните их значения, распределите по эпохам и соотнесите строки с портретами Владимира Святославича и Ивана Грозного.`,
      answer: `Историзмы: гридница — помещение для княжеской дружины; князь — правитель княжества; стольник — придворный чин; боярин — представитель высшего сословия; царь — монарх; барщина — бесплатный труд крепостного на земле помещика; городничий — начальник города; подорожная — документ на получение почтовых лошадей; лапти — плетёная обувь; бурлак — работник, тянувший судно бечевой.\nДревняя Русь: гридница, князь. Более позднее время Российской империи: царь, стольник, боярин, барщина, городничий, подорожная, лапти, бурлак. Слова устарели после исчезновения соответствующих учреждений, сословий, повинностей, профессий и предметов быта.\nПортрет А — Владимир Святославич; ему соответствует строка «Владимир-солнце пировал». Портрет Б — Иван IV Грозный; строка «Сидит грозный царь Иван Васильевич».`,
      rule: `Историзм не имеет современного синонима, потому что вместе со словом исчезла обозначаемая реалия.`,
    },
    15: {
      question: `Проанализируйте отрывок из «Евгения Онегина»: назовите автора, выпишите историзмы, объясните их, опишите картину зимней дороги и приведите другие названия старинного транспорта.`,
      answer: `Автор — А. С. Пушкин.\nИсторизмы: дровни — крестьянские сани без кузова; кибитка — крытая дорожная повозка; ямщик — возница почтовых лошадей; облучок — передняя часть повозки, где сидит возница; кушак — широкий матерчатый пояс; тулуп — длинная меховая верхняя одежда.\nКартина: зимняя дорога оживлена, по свежему снегу быстро идут сани и кибитки, укутанный ямщик сидит впереди. Глагол «летит» передаёт большую скорость, а «рысью» называет быстрый, но ровный ход лошади.\nДругие слова этой группы: карета, бричка, тарантас, почтовая тройка, колымага, дилижанс.`,
      rule: `В художественном тексте историзмы одновременно называют реалии эпохи и создают исторический колорит.`,
    },
    16: {
      question: `Проанализируйте историзмы, объясните их значения и распределите по тематическим группам таблицы.`,
      answer: `Сословия, должности и занятия: барин — помещик, хозяин; городовой — низший полицейский чин; дьяк — служащий государственного учреждения; исправник — начальник уездной полиции; писарь — служащий, занимавшийся письмом; статс-дама — придворное звание.\nОружие, снаряжение и воины: берендейка — перевязь с зарядами; пищаль — старинное огнестрельное оружие; секира — боевой топор; лучник — воин с луком; латник — воин в латах.\nПредметы быта: лучина — тонкая щепка для освещения; светец — подставка для лучины; конторка — высокая наклонная подставка для письма; рукомойник — сосуд для умывания.\nОдежда: кафтан — длинная верхняя одежда; камзол — короткая мужская одежда; армяк — крестьянский кафтан из грубой ткани; салоп — женская верхняя одежда; кокошник — старинный женский головной убор.\nМеры: аршин — 71,12 см; верста — около 1,067 км; десятина — около 1,09 га; пуд — 16,38 кг.`,
      rule: `Тематическая классификация объединяет слова по сфере обозначаемых реалий.`,
    },
    17: {
      question: `Рассмотрите изображение русских стрельцов. Опишите их одежду и вооружение, используя историзмы.`,
      answer: `Стрельцы одеты в длинные цветные кафтаны, высокие шапки и сапоги. Через плечо у них перекинуты берендейки с отдельными футлярами для пороховых зарядов. Вооружены они пищалями, саблями и бердышами — широкими боевыми топорами на длинных древках. Такая одежда и снаряжение характерны для стрелецкого войска Русского государства XVI–XVII веков.`,
      rule: `Описание изображения строится от общего вида к деталям: одежда, снаряжение, оружие и исторический вывод.`,
    },
    18: {
      question: `Определите историзмы по восьми толкованиям, используя слова для справок.`,
      answer: `1) Ендова — древнерусский широкий сосуд с носиком для вина, пива или мёда.\n2) Братина — старинный шаровидный сосуд, из которого пили на братских пирах.\n3) Держава — золотой шар с крестом, символ власти монарха.\n4) Приказ — центральное учреждение Русского государства XVI — начала XVIII века.\n5) Арапник — длинная охотничья плеть.\n6) Коробейник — мелкий торговец-разносчик.\n7) Камердинер — личный слуга барина.\n8) Камеристка — комнатная служанка при барыне или госпоже.`,
      rule: `Для определения историзма сопоставляем ключевые признаки толкования с назначением предмета, учреждения или профессии.`,
    },
    19: {
      question: `Определите произведения и исторические события по двум отрывкам, найдите историзмы и объясните их значения.`,
      answer: `Первый отрывок — «Слово о полку Игореве». Он посвящён походу князя Игоря Святославича против половцев в 1185 году. Историзмы: дружина — княжеское войско; рать — войско; стремя — часть конской сбруи, в которую всадник ставит ногу.\nВторой отрывок — стихотворение М. Ю. Лермонтова «Бородино» о Бородинском сражении 1812 года. Историзмы: уланы — лёгкие кавалеристы с пиками; драгуны — конные воины, способные сражаться и пешими; кивер — высокий военный головной убор; значки — небольшие воинские знамёна.`,
      rule: `Сначала узнаём произведение по ключевой цитате, затем связываем реалии текста с исторической эпохой.`,
    },
    20: {
      question: `Проанализируйте словарные статьи к словам «брегет» и «кивер». Расскажите, как устроена статья словаря устаревших слов и какие сведения из неё можно получить.`,
      answer: `Брегет — карманные часы с боем, показывавшие также число месяца; слово происходит от фамилии французского часовщика А.-Л. Бреге. Кивер — высокий военный головной убор из твёрдой кожи или сукна, распространённый в европейских и русских армиях XVIII–XIX веков.\nСловарная статья включает заголовочное слово и ударение, грамматические сведения, толкование значения, указание эпохи и сферы употребления, происхождение слова, примеры из художественных произведений и иногда иллюстрацию. По ней можно узнать правильное написание и произношение, значение, историю предмета, время употребления слова и увидеть его в контексте.`,
      rule: `Структуру словарной статьи определяем по её постоянным частям: заголовок, пометы, толкование, происхождение, примеры и иллюстрации.`,
    }
  };

  Object.assign(solutions, {
    21: {
      question: `Определите, к каким периодам истории России относятся три ряда устаревших слов, и объясните значения слов.`,
      answer: `1) Древняя Русь и Русское государство: Боярская дума — совет при князе или царе; холоп — зависимый человек; воевода — военный начальник и правитель; смерд — зависимый земледелец.\n2) Российская империя: дворянин — представитель привилегированного сословия; приказчик — наёмный управляющий или продавец; подорожная — документ на получение почтовых лошадей; гусар — воин лёгкой кавалерии; гувернёр — домашний воспитатель.\n3) Советский период: колхоз — коллективное хозяйство; совхоз — государственное хозяйство; Совет народных депутатов — выборный орган власти; соцсоревнование — соревнование трудовых коллективов; коллективизация — объединение крестьянских хозяйств; кулак — зажиточный крестьянин в советской терминологии; комиссар — политический или административный представитель власти; Красная армия — вооружённые силы Советской России и СССР.`,
      rule: `Историзмы распределяются по эпохам через обозначаемые ими учреждения, сословия и общественные отношения.`,
    },
    22: {
      question: `Выберите историзмы одной тематической группы и подготовьте сообщение с презентацией о словах и обозначаемых ими предметах.`,
      answer: `Тема сообщения: «Старинные русские головные уборы». Кокошник — праздничный женский головной убор с высоким украшенным передом. Кичка — замужний женский убор с выступами, напоминавшими рога. Повойник — мягкая шапочка, полностью закрывавшая волосы замужней женщины. Картуз — мужской головной убор с козырьком. Треух — тёплая шапка с тремя опускающимися лопастями. Шапка Мономаха — символ венчания русских государей. Эти слова стали историзмами, потому что сами предметы вышли из повседневного употребления.\nПлан презентации: 1) что такое историзм; 2) изображения шести уборов; 3) их назначение и владельцы; 4) эпоха употребления; 5) следы в музеях, костюме и литературе; 6) вывод.`,
      rule: `Хорошее сообщение объединяет слова одной темы и для каждого даёт значение, эпоху и наглядный пример.`,
    },
    23: {
      question: `Свяжите слова с событиями русской истории, определите историзмы и объясните их значения.`,
      answer: `Слова относятся прежде всего к революции, Гражданской войне и коллективизации. Продотряд — отряд, изымавший хлеб у крестьян; кулак — зажиточный крестьянин в советской терминологии; раскулачивание — лишение зажиточных крестьян имущества и выселение; красноармеец — боец Красной армии; белогвардеец — участник Белого движения; бронепоезд — бронированный железнодорожный состав; будёновец — боец Первой конной армии или носитель шлема-будёновки; тачанка — конная повозка с пулемётом.\nИсторизмы: продотряд, кулак в данном значении, раскулачивание, красноармеец, белогвардеец, будёновец, тачанка. «Бронепоезд» и «пулемётчик» называют реально существующие и теперь предметы и профессии, поэтому не обязательно являются историзмами.`,
      rule: `Не каждое слово из исторического текста — историзм: обозначаемая реалия должна исчезнуть из современной жизни.`,
    },
    24: {
      question: `Распределите устаревшие слова по темам, объясните причины их устаревания и подготовьте проект об их знании современными школьниками.`,
      answer: `Тематические группы: техника для показа и воспроизведения — фильмоскоп, граммофон; освещение и приготовление пищи — керосиновая лампа, примус; вычислительная и музыкальная техника — мини-ЭВМ, дискета. Слова устарели, потому что соответствующие устройства были заменены проекторами, аудиосистемами, электрическим освещением, плитами, современными компьютерами и облачными носителями. Историзмы недавнего времени: пейджер, видеокассета, телетайп, таксофон, счёты, диапроектор.\nПроект: выбрать 30 слов, провести анонимный опрос, отметить ответы «знаю», «примерно знаю», «не знаю», построить диаграмму и сравнить результаты разных возрастов. Ожидаемый вывод: чем быстрее меняется техника, тем быстрее её названия переходят в пассивный запас.`,
      rule: `Причина устаревания технической лексики — исчезновение устройства после появления более удобной технологии.`,
    },
    25: {
      question: `Объясните значения фразеологизмов и найдите в них историзмы.`,
      answer: `Турусы на колёсах — нелепые выдумки или пустые разговоры; затрапезный вид — неряшливый, убогий вид; перековать мечи на орала — перейти от войны к мирному труду; бразды правления — руководство, власть.\nТурусы — передвижные деревянные осадные башни, поэтому это историзм. Затрапезом называли грубую полосатую ткань, название которой связано с фабрикантами Затрапезновыми; это старинное слово. Орало — старое название плуга, бразды — поводья; это архаизмы, потому что предметы сохранились, но называются иначе.`,
      rule: `В устойчивом выражении может сохраняться слово, которое отдельно уже не употребляется.`,
    },
    26: {
      question: `Прочитайте фрагмент письма Д. С. Лихачёва «О памяти». Объясните выражение «генетическая память» и напишите рассуждение о роли историзмов в сохранении памяти.`,
      answer: `Генетическая память — память, передающаяся от одного поколения живых существ следующим. Автор показывает, что память есть у материи, природы и человека, но человеческая память особенно важна: она творчески накапливает опыт, создаёт традиции и противостоит разрушительному времени.\nИсторизмы необходимы генетической и культурной памяти народа. Слова «дружина», «стрелец», «барщина», «ямщик» сохраняют сведения о войске, общественном устройстве, труде и быте прошлых эпох. Без их знания читатель неправильно поймёт летопись, исторический документ или классическое произведение. Следовательно, изучая историзмы, мы сохраняем связь поколений и точнее понимаем историю страны.`,
      rule: `Рассуждение строится по схеме: тезис → объяснение → примеры → вывод.`,
    },
    27: {
      question: `Перепишите текст о слове «левый», вставляя буквы, раскрывая скобки и расставляя знаки препинания.`,
      answer: `В глубокой древности слово «левый» не обозначало направления («в сторону левой руки»; «там, где сердце»), но имело целый ряд других значений — «кривой», «ложный» («нечестный»). Сказка недаром сохранила указание: «Налево пойдёшь — смерть найдёшь». Левая сторона в сказке — сторона злой силы, левый царь — недобрый царь, левая часть — подземное царство. Слово «левый» сменило в XI веке более раннее слово «шуя», у которого было одно значение — «левый, сторонний». Вытеснив это слово, «левый» сохранило и прежние значения. Оно стало обозначать и «левый», и «кривой», и «ложный».`,
      rule: `Чужие значения и цитаты заключаются в кавычки; пояснение после обобщающей части отделяется тире.`,
    },
    28: {
      question: `Прочитайте фрагмент Н. М. Шанского об историзмах и архаизмах, сформулируйте тему, основные мысли и сложный план.`,
      answer: `Тема — различие историзмов и архаизмов. Основная мысль: причины и результат устаревания этих двух групп различны. Историзмы — единственные названия исчезнувших реалий и не имеют современных синонимов; у архаизмов есть действующие слова-синонимы, а причины их вытеснения сложнее и требуют языкового исследования.\nСложный план:\n1. Историзмы в пассивном словаре. а) Единственное название исчезнувшей реалии. б) Отсутствие современного синонима.\n2. Архаизмы в современном языке. а) Наличие активного синонима. б) Замена одного слова другим.\n3. Разные причины устаревания. а) Понятная связь историзмов с исчезновением реалий. б) Сложность объяснения появления архаизмов.`,
      rule: `В сложном плане крупные смысловые части делятся на подпункты, которые раскрывают доказательства автора.`,
    },
    29: {
      question: `По схеме расскажите о типах архаизмов и приведите свои примеры.`,
      answer: `Архаизмы бывают лексическими и лексико-семантическими. В лексическом архаизме устарело всё слово; в лексико-семантическом — только одно его значение.\nЛексические делятся на: собственно лексические — уста (губы), ланиты (щёки), рамена (плечи); словообразовательные — рыбарь (рыбак), воитель (воин), дружество (дружба); морфологические — лебедь белая (совр. белый лебедь), в постелю (в постель); фонетические — град (город), злато (золото), брег (берег).\nЛексико-семантические: живот в значении «жизнь», язык в значении «народ», свет в значении «мир, общество».`,
      rule: `Тип архаизма определяется тем, что именно устарело: всё слово, суффикс, форма, звуковой облик или отдельное значение.`,
    },
    30: {
      question: `Найдите в отрывке из «Бориса Годунова» историзмы и архаизмы, объясните значения и определите типы архаизмов.`,
      answer: `Историзмы: дьяк — государственный служащий; приказ — центральное учреждение Русского государства XVI–XVII веков.\nАрхаизмы: зрит — смотрит (собственно лексический); правых — невиновных (лексико-семантический); внимая — слушая внимательно (собственно лексический); не ведая — не зная (собственно лексический).\nСовременный вариант: «Так точно служащий, состарившийся на государственной службе, спокойно смотрит на невиновных и виновных, равнодушно выслушивая добро и зло, не зная ни жалости, ни гнева».`,
      rule: `Историзмы называют исчезнувшие должности и учреждения, а архаизмы заменяются современными синонимами.`,
    },
    31: {
      question: `Найдите архаизмы в восьми цитатах, объясните их и распределите по типам.`,
      answer: `Собственно лексические: рыбарь — рыбак; пиит — поэт; око — глаз; взирать — смотреть; дольний — земной; иллюзион — старое название кинотеатра.\nЛексико-семантические: глава — голова; мир в сочетании «мир дольний» — земная жизнь.\nЛексико-словообразовательные: рыбарь — рыбак (различаются суффиксами), надменный в старом книжном употреблении — высокомерный.\nЛексико-фонетические: аглицкий — английский; клоб — клуб; злато — золото; синематограф — кинематограф.`,
      rule: `Для классификации сравниваем старое слово с современным: основу, суффикс, форму и звуковой состав.`,
    },
    32: {
      question: `Подберите современные соответствия к лексическим архаизмам и запишите пары.`,
      answer: `Длань — ладонь; извет — донос; тать — вор; фрунт — строй; балтический — балтийский; зерцало — зеркало; лицедей — актёр; брадобрей — парикмахер; перси — грудь.`,
      rule: `Современное соответствие должно передавать то же значение без устаревшей окраски.`,
    },
    33: {
      question: `Найдите лексико-семантические архаизмы, объясните устаревшие значения и назовите современные значения тех же слов.`,
      answer: `Язык — в цитате «народ»; сегодня прежде всего орган речи или система общения. Прах — «пыль»; современное книжное значение — останки умершего. Летник — старинная женская верхняя одежда; теперь слово может означать человека, работающего или живущего летом. Роба — платье, одежда; сейчас — грубая рабочая или тюремная одежда. Класс — разряд или группа извозчиков; сегодня — школьный коллектив, помещение или категория предметов. Троечник — извозчик на тройке; сегодня — ученик с отметками «три». Одиночник — извозчик с одной лошадью; сегодня — человек, действующий один.\nУстаревшее значение описывают отдельно, потому что оно заметно отличается от современного и требует собственной пометы и примеров.`,
      rule: `Лексико-семантический архаизм — это сохранившееся слово с исчезнувшим старым значением.`,
    },
    34: {
      question: `Проанализируйте словарные статьи к словам «старец» и «пастырь», найдите семантические архаизмы и приведите другие примеры.`,
      answer: `У слова «старец» устарело значение «уважаемый, почтенный пожилой человек»; значение «старый монах, отшельник» сохраняется как историко-религиозное. У слова «пастырь» устарело значение «пастух», а книжное переносное значение «священник — духовный наставник паствы» употребляется и сейчас.\nДругие лексико-семантические архаизмы: живот — жизнь («не щадя живота»); позор — зрелище; гость — купец; язык — народ; свет — мир или общество; красный — красивый.`,
      rule: `Помета «устар.» может относиться не ко всему слову, а только к одному из его значений.`,
    },
    35: {
      question: `Объясните фразеологизмы, выпишите сохранившиеся в них устаревшие слова и определите их разряд.`,
      answer: `Быльём поросло — давно забыто; бить баклуши — бездельничать; точить лясы — болтать; гол как сокол — совершенно беден; попасть впросак — оказаться в неловком положении.\nУстаревшие слова: быльё — сорная трава; баклуши — деревянные заготовки для ложек; лясы — резные столбики или праздные разговоры; сокол — старинное гладкое стенобитное орудие; просак — станок для кручения верёвок. Эти слова относятся к старинным словам и историзмам, сохранившимся главным образом внутри устойчивых выражений.`,
      rule: `Значение фразеологизма не равно простой сумме значений его частей, поэтому старое слово проверяется по этимологическому словарю.`,
    },
    36: {
      question: `Восстановите девять фразеологизмов с архаизмами, объясните их и определите тип архаизмов.`,
      answer: `1) Беречь как зеницу ока — очень тщательно беречь. 2) Один как перст — совсем один. 3) С головы до пят — целиком. 4) Бить челом — почтительно просить или благодарить. 5) В мгновение ока — мгновенно. 6) Из уст в уста передавать — сообщать друг другу. 7) Идти по пятам — следовать совсем близко. 8) Ни кола ни двора — ничего не иметь. 9) Глас вопиющего в пустыне — напрасный призыв.\nЗеница — зрачок, око — глаз, перст — палец, чело — лоб, уста — губы/рот, глас — голос, пята — задняя часть стопы. Это собственно лексические архаизмы; современные синонимы имеют другую основу.`,
      rule: `Фразеологизм восстанавливается в устойчивой форме, слова в нём нельзя произвольно заменять.`,
    },
    37: {
      question: `Найдите в материалах параграфа старославянизмы, ставшие фонетическими архаизмами, и назовите их тематические группы.`,
      answer: `Примеры: град — город (населённые пункты); глава — голова (части тела); злато — золото (металлы и богатство); хлад — холод (состояние среды); брег — берег (география); млеко — молоко (пища); врата — ворота (постройки); древо — дерево (растения). Они отличаются от современных русских соответствий неполногласием -ра-, -ла-, -ре-, -ле- вместо -оро-, -оло-, -ере-.`,
      rule: `Характерная фонетическая пара: старославянское неполногласие — русское полногласие.`,
    },
    38: {
      question: `Разберите архаизмы в стихотворении А. С. Пушкина «Пророк»: назовите произведение и тему, определите типы слов и их художественную функцию.`,
      answer: `Это стихотворение «Пророк», его тема — духовное преображение поэта и его высокое предназначение говорить людям правду.\nВ начале: влачился — медленно и тяжело шёл; перстами — пальцами; зениц — глаз/зрачков. В полном тексте: отверзлись — открылись; внял — услышал; горний — небесный; дольний — земной; уста — губы; десница — правая рука; перси — грудь; глас — голос; виждь — смотри; внемли — слушай; глаголом — словом. Большинство — собственно лексические архаизмы, формы «виждь», «внемли» — грамматические.\nАрхаизмы создают библейскую торжественность, высокий стиль и подчёркивают пророческую миссию поэта. Такая функция особенно характерна для высокой поэзии XVIII — первой трети XIX века.`,
      rule: `Художественную функцию определяем по тому, какое настроение создаёт устаревшая лексика в контексте.`,
    },
    39: {
      question: `Найдите архаизмы в отрывке из романа А. Н. Толстого «Пётр I», определите их функцию и сравните с историзмами в отрывке из «Бориса Годунова».`,
      answer: `Архаизмы: восприял — приобрёл, почувствовал; бранное поле — поле битвы; дабы — чтобы; баталия — сражение; конфузия — поражение, неудача. Слова и обороты стилизуют речь под начало XVIII века и воссоздают исторический колорит, а не создают торжественный стиль.\nВ «Борисе Годунове» историзмы «дьяк» и «приказ» точно называют исчезнувшие должность и учреждение. Их функция та же — показать эпоху, но историзмы называют её реалии, а архаизмы передают старинную манеру речи.\nВывод: в исторической прозе архаизмы и историзмы совместно создают ощущение времени, однако выполняют это разными языковыми средствами.`,
      rule: `Историзм называет предмет эпохи, а стилистический архаизм имитирует её речь.`,
    },
    40: {
      question: `Найдите архаизм в отрывке из басни С. В. Михалкова «Назойливый комар» и объясните цель его употребления.`,
      answer: `Архаизм — «пиит», то есть поэт. Он использован для комического эффекта: высокое старинное название поэта сталкивается с нелепым образом самодовольного комара, который всего лишь научился пищать в рифму. Автор иронизирует над бездарностью и чрезмерным самомнением героя.`,
      rule: `Комизм возникает из контраста между высоким словом и нарочно низким или смешным предметом.`,
    }
  });

  Object.assign(solutions, {
    41: {
      question: `По схеме сделайте вывод о стилистических функциях архаизмов и историзмов в художественном тексте и подтвердите его примерами.`,
      answer: `Архаизмы и историзмы выполняют три основные функции. Во-первых, создают торжественный высокий стиль: «Глаголом жги сердца людей» у А. С. Пушкина. Во-вторых, называют исчезнувшие реалии и передают колорит эпохи: дьяк, приказ, боярин, стрелец. В-третьих, создают комический или сатирический эффект, если высокое старое слово относится к нарочно смешному предмету: комар «пиитом возомнил себя». Следовательно, функция устаревшего слова определяется контекстом, а не только его словарным значением.`,
      rule: `Вывод по схеме должен содержать общий тезис и отдельный пример к каждой ветви.`,
    },
    42: {
      question: `Прочитайте отрывок Ф. Искандера о Савельиче. Назовите черту героя, найдите устаревшую лексику и объясните авторское понимание его «рабства».`,
      answer: `Главная черта Савельича — преданность. Он бережёт Гринёва не из страха, а по внутреннему нравственному выбору. Историзмы «холоп», «крепостной», «барчук», «барин» называют отношения крепостной России. Слова «раб» и «холопство» в тексте употреблены переносно — как внешняя покорность и зависимое поведение.\nАвтор называет рабство только внешней оболочкой, потому что сущность героя — свободная нравственная верность. Раб можно подчиниться из страха, а Савельич добровольно рискует собой ради другого человека. Я согласен с Ф. Искандером: преданность, основанная на любви и ответственности, выше общественного положения и не равна рабской покорности.`,
      rule: `Авторская позиция раскрывается через противопоставление внешнего поведения и внутренних мотивов героя.`,
    },
    43: {
      question: `Подготовьте проект на одну из тем о связи русского языка с историей и памятью народа.`,
      answer: `Проект «Слова русского языка как зеркало истории». Цель — показать, что словарь хранит сведения о жизни народа.\n1. Государство и общество: князь, боярин, дьяк, приказ, губерния. 2. Военное дело: дружина, стрелец, пищаль, бердыш. 3. Труд и быт: барщина, ямщик, лучина, рукомойник. 4. Советская эпоха: колхоз, пионер, пятилетка. 5. Новейшее время: интернет, блогер, смартфон.\nДля каждого слова в презентации указываются значение, время употребления, иллюстрация и пример из текста. Вывод: предмет или учреждение может исчезнуть, но его название остаётся в книгах и сохраняет культурную память. Поэтому знание устаревшей лексики помогает понимать историю и классическую литературу.`,
      rule: `Проект включает тему, цель, материал по смысловым разделам, примеры, иллюстрации и общий вывод.`,
    },
    44: {
      question: `Перепишите отрывок А. Н. Толстого, вставляя пропущенные буквы и расставляя знаки препинания.`,
      answer: `Многое мог увидеть пращур, глядя из-под ладони по солнцу... «Ничего, мы сдюжим», — сказал он и начал жить. Росли и множились позади него могилы отцов и дедов, рос и множился его народ. Дивной вязью он плёл невидимую сеть русского языка: яркого, как радуга, — вслед ливню, меткого, как стрелы, задушевного, как песня над колыбелью, певучего и богатого. Он назвал вещи своими именами и воспел свой труд. И дремучий мир, на который он накинул волшебную сеть слова, покорился ему, как обузданный конь, и стал его достоянием, и для потомков его стал родиной — землёй отчич и дедич.`,
      rule: `Сравнительные обороты обособляются, прямая речь отделяется от слов автора, однородные определения разделяются запятыми.`,
    },
    45: {
      question: `Проанализируйте отрывок Ю. С. Павловой о путешествии школьника в 1970 год: распределите лексику между активным и пассивным запасом и объясните различие понимания слов героями.`,
      answer: `Непривычные для современного героя реалии 1970 года: пионерская форма, пионерский галстук, октябрёнок, совет пионерской дружины, школьная семилетка и десятилетка, счёты, чернильница-непроливайка, промокашка, пишущая машинка, машинистка. Это историзмы или малоупотребительные слова.\nШкольники 1970 года не знали бы современных значений и названий: мобильник, интерактивная доска, компьютер, принтер, Интернет, гаджет, дисплей, флешка, стикер, фломастер, маркер. Они появились вместе с новыми технологиями и вошли в активный запас.\nПо-разному могли быть поняты слова «линейка» (торжественное построение или измерительный инструмент), «галстук» (пионерский платок или деталь костюма), «машинка» (пишущая машинка или устройство/автомобиль), «перо» (стальная часть ручки или птичье перо). Активный запас зависит от эпохи и опыта носителя языка.`,
      rule: `Активная лексика понятна и регулярно употребляется современниками; пассивная связана с ушедшими реалиями или редкой сферой.`,
    },
    46: {
      question: `Сравните словарные толкования слов, вернувшихся в активный запас, в словарях середины XX и начала XXI века. Объясните изменения значений и окраски.`,
      answer: `Губернатор: раньше — начальник губернии царской России или зарубежной области; теперь — глава крупного региона, в том числе субъекта России. Кадет: раньше — воспитанник дореволюционного военного корпуса для дворян; теперь — учащийся кадетского корпуса или школы. Благотворительность: советский словарь давал отрицательно-идеологическое толкование частной помощи; современное значение нейтрально — материальная помощь нуждающимся. Дивиденд: прежде связывался только с капиталистическим обществом; теперь — часть прибыли акционера и переносно «выгода». Коммерсант: прежде «крупный торговец в буржуазном обществе»; теперь нейтрально «человек, занимающийся коммерцией».\nУстаревшими были «губернатор» и «кадет»; «благотворительность», «дивиденд», «коммерсант» были малоупотребительными и идеологически окрашенными. После общественных изменений они стали нейтральнее, расширили значения и вернулись в активную речь.`,
      rule: `Сравниваем не только определение, но и временные, территориальные и оценочные пометы.`,
    },
    47: {
      question: `Докажите по словарным статьям к словам «дворянство» и «двуглавый», что это возвращённая лексика, пополнившая активный запас.`,
      answer: `«Дворянство» в дореволюционной России называло привилегированное сословие. После его исчезновения слово стало историзмом, но в конце XX — начале XXI века появилось новое активное значение: общественная группа, относящая себя к потомкам этого сословия.\n«Двуглавый» означает «имеющий две головы». Сочетание «двуглавый орёл» вновь стало общеупотребительным после возвращения этого изображения в государственный герб России в 1990-е годы. Значит, оба слова вернулись вслед за общественными и государственными реалиями, хотя старые и новые значения совпадают не полностью.`,
      rule: `Возвращённое слово снова становится частотным, когда возвращается реалия или возникает её современный аналог.`,
    },
    48: {
      question: `Найдите в литературных цитатах слова, вернувшиеся в активный запас, сопоставьте их со значениями и объясните, у каких слов значение изменилось.`,
      answer: `Возвращённые слова: департамент — отдел министерства; институт — теперь главным образом высшее учебное или научное учреждение; госпожа — вежливое обращение к женщине; ботфорты — сапоги с высоким голенищем; дума — современный представительный орган; благотворительность — добровольная помощь нуждающимся.\nИсторизмами остаются дьяк, городничий, полицмейстер, квартальный — соответствующих должностей сейчас нет. Слова «имение», «камерка», «прислуга» понятны, но редки или стилистически окрашены.\nСильнее всего изменились значения «институт» и «дума»: современная реалия отличается от дореволюционной. «Департамент», «госпожа» и «ботфорты» вернулись в близком значении.`,
      rule: `Нужно различать вернувшееся слово, историзм и слово, сохранившееся лишь как редкое или стилистически окрашенное.`,
    },
    49: {
      question: `Проанализируйте пары старых и современных названий городов, назовите возвращённые исторические имена и приведите свои примеры.`,
      answer: `Пары: Тверь — Калинин; Екатеринбург — Свердловск; Нижний Новгород — Горький; Вятка — Киров. В активный запас вернулись исторические названия Тверь, Екатеринбург и Нижний Новгород. Название Вятка остаётся историческим, современное официальное название города — Киров.\nДругие примеры: Санкт-Петербург — Ленинград; Самара — Куйбышев; Оренбург — Чкалов; Сергиев Посад — Загорск; Рыбинск — Андропов; улица Тверская — улица Горького — Тверская. Возвращение названий связано с восстановлением исторической памяти.`,
      rule: `Пары составляются между названиями одного населённого пункта в разные исторические периоды.`,
    },
    50: {
      question: `Определите по толкованиям слова религиозной и православной тематики, вернувшиеся в активное употребление.`,
      answer: `1) Благовест — звон в один колокол перед службой. 2) Ближний — всякий другой человек по отношению к человеку. 3) Воскресная школа — учебное заведение при церкви. 4) Гордость — первый из семи смертных грехов. 5) Диакон — нижняя степень церковной иерархии, помощник священника. 6) Духовник — священник, руководящий духовной жизнью верующего. 7) Иконописец — мастер, пишущий иконы. 8) Лавра — большой мужской монастырь особого значения. 9) Милосердие — сострадательная помощь ближнему. 10) Пасха — главный христианский праздник Воскресения Христова.\nЭти слова вернулись в широкую речь после восстановления религиозной жизни, храмов, образования и традиций.`,
      rule: `Толкование распознаётся по отличительному признаку: действию, должности, учреждению, добродетели или празднику.`,
    },
    51: {
      question: `Расскажите о перераспределении слов между активным и пассивным запасом в истории русского языка и дополните примерами.`,
      answer: `Активный запас включает общеупотребительные слова, обозначающие актуальные предметы и понятия; пассивный — устаревшие, редкие и ограниченные слова. После общественных изменений слова могут уйти в пассив: дворянин, городничий, пионерская дружина, дискета. Обратный процесс происходит при возвращении реалии или переоценке понятия: губернатор, кадет, благотворительность, храм, лавра, гимназия. Новые технологии вводят в активный запас слова смартфон, браузер, блог.\nПереход сопровождается изменением значения и окраски. Например, «коммерсант» утратил отрицательную советскую окраску, «дума» стала названием современного органа власти, а «класс» приобрёл новые значения. Словарь языка поэтому постоянно меняется вместе с обществом.`,
      rule: `Перераспределение объясняется связью слова с реальными изменениями общества, культуры и техники.`,
    },
    52: {
      question: `Проанализируйте миниатюру А. И. Солженицына «Путешествуя вдоль Оки»: определите тему, ключевые слова, проблему и напишите рассуждение.`,
      answer: `Тема — русские церкви и колокольный звон как часть родного пейзажа и исторической памяти. Ключевые слова: церкви, колокольни, сёла, звон, вечность, камни, предки. Тематические группы: природа — реки, холмы, поля, лес; архитектура и вера — церковь, колокольня, крест, алтарь; память — предки, вечность, понимание жизни.\nПоследние абзацы говорят: человек занят мелкими делами, а вечерний звон напоминает о вечности; в камни и колокольни предки вложили лучшее понимание жизни. Проблема — утрата духовной и культурной связи с прошлым.\nЯ согласен с автором. Памятники и исторические слова не просто сообщают факты, а дают почувствовать опыт поколений. Если исчезают храмы, старые названия и память о них, пейзаж теряет человеческий смысл. Поэтому культурное наследие необходимо сохранять и осмыслять.`,
      rule: `Анализ объединяет тему, ключевую лексику, авторскую проблему и собственный аргументированный вывод.`,
    },
    53: {
      question: `Подготовьте проект о «Русском словаре языкового расширения» А. И. Солженицына и оцените идею возвращения старых русских слов.`,
      answer: `Проект «Можно ли расширить язык его собственными богатствами?». А. И. Солженицын составил «Русский словарь языкового расширения», отбирая выразительные слова из словаря В. И. Даля и других источников. Его цель — не запретить все заимствования, а вернуть языку забытые русские возможности и создавать слова из понятных отечественных корней.\nДля исследования можно выбрать слова «внимчивый» (внимательный, чуткий), «укрывистый» (дающий хорошее укрытие), «оживляж» (то, что оживляет), «самостояние» (самостоятельная внутренняя опора), проверить их по словарю и опросить одноклассников.\nВывод: возвращение удачно, если слово понятно, точно называет явление и естественно звучит в речи. Искусственное вытеснение привычного международного термина непонятным словом пользы не принесёт. Язык обогащается и внутренним словообразованием, и необходимыми заимствованиями.`,
      rule: `Проект оценивает языковую идею по трём критериям: понятность, точность и возможность реального употребления.`,
    },
    54: {
      question: `Перепишите текст о словарной сокровищнице языка, вставляя буквы, раскрывая скобки и расставляя знаки препинания.`,
      answer: `Как живой архив этнической памяти, словарная сокровищница нашего языка требует к себе исключительно бережного отношения. Нельзя забывать, что именно уважение к прошлому — «черта, отличающая цивилизованность от дикости» (А. С. Пушкин). Поскольку русский язык как творческая способность речемысли живёт в каждом из нас, его носителей, то разрыв историко-культурных традиций приводит к утрате каких-то важных духовных, ментальных «генов», искажая языковую личность.\nДругой перекос — в сторону излишнего калькирования традиционных средств — может создать затруднения в выражении новых идей и понятий.`,
      rule: `Обособляются приложение, причастный и деепричастный обороты; цитата оформляется кавычками и ссылкой на автора.`,
    },
    55: {
      question: `Проанализируйте текст о профессиях будущего: объясните причины их появления, выпишите новые названия по группам и разберите заимствования.`,
      answer: `Новые профессии возникают из-за научно-технического прогресса, цифровизации, робототехники, 3D-печати, развития городов, биотехнологий и новых способов обучения.\nИнформационные технологии: программист, разработчик мобильных приложений, веб-дизайнер. Техника и производство: инженер-робототехник, оператор 3D-принтера. Город и сельское хозяйство: урбанист, сити-фермер. Биология: биотехнолог. Образование: тьютор, игропедагог, тренер по майнд-фитнесу.\nЗаимствования: программист, веб-дизайнер, урбанист, сити-фермер, биотехнолог, тьютор, тренер, майнд-фитнес, 3D. Русские образования и сочетания: разработчик мобильных приложений, игропедагог, оператор объёмной печати. Английских основ много, потому что цифровые технологии и новые профессиональные стандарты часто распространяются через англоязычную международную среду. Латиница сохраняется в 3D и mind-fitness.`,
      rule: `Название профессии связывается с новой сферой деятельности, затем разбирается по происхождению и способу образования.`,
    },
    56: {
      question: `Определите семь новых заимствованных слов по значениям, распределите их по причинам заимствования и подберите русские синонимы.`,
      answer: `1) Девайс — устройство. 2) Мундиаль — чемпионат мира по футболу. 3) Логин — учётное имя пользователя. 4) Гастарбайтер — трудовой мигрант. 5) Модель — человек, демонстрирующий товары. 6) Смартфон — многофункциональный мобильный телефон. 7) Слоган — рекламный или политический лозунг.\nТехника: девайс, логин, смартфон; спорт: мундиаль; экономика и миграция: гастарбайтер; мода и реклама: модель, слоган. Точные русские синонимы возможны у «девайса», «мундиаля», «логина», «гастарбайтера», «слогана»; «смартфон» обозначает особый вид телефона, а «модель» шире слова «манекенщица».`,
      rule: `Причина заимствования определяется сферой новой реалии, а синоним проверяется на полноту совпадения значения.`,
    },
    57: {
      question: `Объясните новые заимствования, распределите их по тематическим группам и отметьте слова, не называющие принципиально новых реалий.`,
      answer: `Информатика и сети: браузер, модем, чат, блог, имейл. Спорт: боулинг, скейтборд, серфинг, бодибилдинг. Оргтехника: ксерокс, маркер, факс, степлер. Массовая культура: селфи, кастинг, рэпер, триллер, анимация, блокбастер. Торговля и реклама: гипермаркет, баннер, прайс-лист. Мода: сникерс, слипоны, топ-модель, бандана. Еда: спагетти, роллы, наггетсы.\nНе всегда обозначают совершенно новое: имейл — электронная почта; прайс-лист — список цен; маркер — фломастер; сникерсы — спортивная обувь; топ-модель — известная модель; анимация — мультипликация; гипермаркет — очень большой магазин. Их распространение объясняется модой, краткостью и международным общением.`,
      rule: `Распределяем слова по сфере, затем проверяем, появилась ли новая реалия или лишь новое название старого понятия.`,
    },
    58: {
      question: `Исследуйте заимствованный фразеологизм из истории слова «наггетсы»: объясните значение, время и путь его появления в русском языке.`,
      answer: `Фразеологизм — «золотая молодёжь»: дети состоятельных и влиятельных родителей, ведущие обеспеченную светскую жизнь. Выражение является калькой французского jeunesse dorée и появилось во Франции после Термидорианского переворота конца XVIII века как название щегольской обеспеченной молодёжи. В русский язык оно пришло через французское культурное влияние в XIX веке и закрепилось в переносном общественном значении.`,
      rule: `Для истории фразеологизма устанавливаются буквальный образ, язык-источник, первоначальная ситуация и современное значение.`,
    },
    59: {
      question: `Проанализируйте пары новых заимствований и русских синонимов, объясните смысловые и стилистические различия.`,
      answer: `Бизнесмен — предприниматель: первое разговорнее и подчёркивает сферу бизнеса, второе официальнее и шире. Имидж — образ: имидж обычно специально создаётся для общественного восприятия, образ может быть любым представлением. Саммит — встреча: саммит — официальная встреча руководителей высшего уровня. Байкер — мотоциклист: байкер принадлежит к особой субкультуре, мотоциклист — любой человек на мотоцикле. Секьюрити — охранник: первое модное разговорное заимствование, второе нейтральное название профессии. СМС — сообщение: СМС — конкретное короткое сообщение по мобильной связи, «сообщение» намного шире.\nПолная замена возможна не всегда: у заимствований часто есть более узкий терминологический или стилистический оттенок.`,
      rule: `Синонимы сравниваются по объёму значения, сфере употребления и стилистической окраске.`,
    },
    60: {
      question: `Найдите ошибки в употреблении новых заимствований в объявлениях и исправьте предложения.`,
      answer: `1) Лучше: «В нашем кафе вы можете заказать блюда быстрого приготовления». Фастфуд — вид пищи, а не отдельное блюдо, которое «отведывают».\n2) «Дорогие посетители! Не бросайте мусор на пол. Уважайте труд уборщиков». «Специалисты по клинингу» здесь неоправданно громоздко.\n3) «В торговый зал требуется мерчандайзер» или «В торговый ларёк требуется помощник продавца». Мерчандайзер не является названием должности помощника продавца: он отвечает за выкладку и представление товара.\n4) «К забронированной ещё зимой гостинице можно было добраться только на фуникулёре». Мотель предназначен прежде всего для автомобилистов и обычно расположен у дороги, поэтому контекст фуникулёра ему противоречит.`,
      rule: `Заимствование уместно только тогда, когда его точное значение соответствует ситуации и оно не усложняет простое сообщение.`,
    }
  });

  Object.assign(solutions, {
    61: {
      question: `Проанализируйте текст о школьниках, гаджетах и Интернете: выпишите новые заимствования и русские образования, объясните их значение и сформулируйте основную мысль.`,
      answer: `Заимствования: гаджет — электронное устройство; Интернет — всемирная сеть; сайт — страница или система страниц в сети; геймер — любитель компьютерных игр; пост — публикация; репост — повторная публикация; лайк — отметка одобрения; селфи — фотография самого себя. Русские образования от заимствованных основ: интернет-зависимость, интернет-сообщество, лайкать, репостить.\nРазговорные и жаргонные слова: геймер, лайкать, репостить; в нейтральном тексте лучше «игрок», «отметить как понравившееся», «поделиться публикацией».\nОсновные мысли: Интернет полезен для общения и поиска информации, но чрезмерное увлечение играми и соцсетями вызывает зависимость и мешает учёбе; виртуальная среда бывает опасна. Я согласен: важны ограничение времени, проверка источников и отказ от общения с подозрительными незнакомцами.`,
      rule: `Лексику распределяем по происхождению и окраске, а позицию автора подтверждаем фактами из текста.`,
    },
    62: {
      question: `Разберите слова с заимствованными основами и русскими суффиксами, сравните грамматические и стилистические особенности двух групп.`,
      answer: `Первая группа — относительные прилагательные: брокер-ск-ий, хакер-ск-ий, онлайн-ов-ый, клип-ов-ый, сноуборд-ист-ск-ий. Вторая группа — существительные: флеш-к-а, компьютер-щик, аниме-шник, форум-чан-ин, байкер-ш-а.\nСлова образованы по русским моделям и изменяются по правилам русского языка, поэтому являются освоенными русским словообразованием, хотя их основы заимствованы. Первая группа преимущественно нейтральна; во второй заметна разговорная окраска суффиксов -щик-, -шник-, -чанин-, -ша. В официальной речи лучше: специалист по компьютерам, поклонник аниме, участник форума, женщина-байкер.`,
      rule: `Происхождение основы и принадлежность производного слова к русской словообразовательной системе — разные признаки.`,
    },
    63: {
      question: `Сопоставьте высказывания двух лингвистов об англицизмах, определите проблему и подготовьте позицию для дискуссии.`,
      answer: `Проблема — где проходит граница между полезным заимствованием и засорением речи. Первый автор критикует бездумную замену русских слов модными англицизмами и видит в ней неуважение к языку. Второй показывает естественное освоение: слово «пиар» получило русские формы «пиарщик», «пиар-кампания», «пропиарить» и стало своим по грамматике.\nМоя позиция: заимствование оправданно, если точно и кратко называет новое понятие. Если есть ясный русский эквивалент, лучше выбирать его: магазин вместо шопа, охранник вместо секьюрити. Но слова компьютер, браузер, сайт уже нужны и освоены. Критерии — точность, понятность адресату, уместность стиля и соблюдение русских норм.`,
      rule: `В дискуссии нужно представить обе позиции, критерии оценки и собственный вывод с примерами.`,
    },
    64: {
      question: `Перепишите текст об иноязычных словах, вставляя буквы, раскрывая скобки и расставляя знаки препинания.`,
      answer: `Не всякое иноязычное слово может расцениваться как лишнее, как засоряющее родную речь: во многих случаях заимствование или называет какой-то новый предмет, не имеющий русского наименования, или уточняет какое-либо понятие, или, коротко, одним словом называет то, что по-русски можно назвать описательно, с помощью нескольких слов.\nЭто, конечно, не значит, что иноязычное всегда лучше своего, родного. История русского языка свидетельствует как раз о том, что многие заимствованные слова, бывшие в употреблении в XIX веке, бесследно исчезли, и говорящие по-русски нисколько не пожалели об этом. Что имел в виду Гоголь, когда в «Мёртвых душах» писал о даме, с которой приключилось «небольшое пикнодитце»? Сейчас не всякий словарь даст нам ответ, и мы узнаем, что «пикнодитце» означает по-русски просто неудобство, неловкость.\nВозможно, и кое-какие из слов-иностранцев, появившихся в последние десятилетия, канут в безвестность, уйдут из нашего языка. Но коль скоро они употребляются сейчас, мы должны знать, что они значат, как соотносятся с близкими по смыслу русскими словами, как надо правильно писать и произносить и так далее.`,
      rule: `Однородные придаточные разделяются запятыми; вводное слово «конечно» обособляется; не с местоимением пишется раздельно.`,
    },
    65: {
      question: `Раскройте ключевые слова раздела «Язык и культура» и объясните смысл эпиграфа.`,
      answer: `Историзмы называют исчезнувшие реалии; архаизмы — устаревшие названия существующих понятий; старинные слова могут сохраняться во фразеологизмах. Активный запас — регулярно употребляемая лексика, пассивный — устаревшая и редкая. Возвращение слова связано с возвращением реалии; внешние факторы развития языка — изменения истории, культуры, науки и контакты народов. Заимствования бывают оправданными, когда называют новое или уточняют понятие, и неоправданными, когда без нужды вытесняют ясное русское слово.\nСмысл эпиграфа: язык — главное средство мышления, общения и сохранения культуры; владеть им — значит выбирать точные, уместные слова и уважать накопленный народом опыт.`,
      rule: `Ключевое слово раскрывается через краткое определение и связь с общей темой раздела.`,
    },
    66: {
      question: `Проанализируйте стихотворение М. И. Цветаевой «Домики старой Москвы»: определите тему, нарушение нормы ударения и выразительные средства.`,
      answer: `Тема — исчезновение старых московских домов и грусть по уходящей культуре города. Современную Москву фотография не подтверждает: поэт описывает Москву прежней эпохи.\nВ строке «на вековых воротах» ради рифмы со словами «аккорды — морды» подразумевается старое ударение «воро́тах/во́ротах»; современная норма — на ворота́х. Оно сохраняет историческую окраску стиха.\nКартины: скромные переулки, дома как ледяные дворцы, расписные потолки и зеркала, клавесины, ворота с львиными мордами, тёмные комнаты. Чувство — любовь, восхищение и печаль. Средства: обращения, риторические вопросы, сравнение «точно дворцы ледяные», эпитеты, перечисления, олицетворение домов.`,
      rule: `Поэтическое отступление от современной нормы проверяется по рифме и орфоэпическому словарю.`,
    },
    67: {
      question: `Сравните ударение в двух отрывках А. С. Пушкина с современной нормой и назовите народную традицию во втором отрывке.`,
      answer: `В «К морю» слово «о́тзывы» у Пушкина читается как «отзы́вы», чтобы рифмоваться со словом «поры́вы»; современная норма — о́тзывы. Такое расхождение объясняется историческим изменением ударения. Остальные ключевые формы читаются по современной норме: красо́й, глас, проводи́в, твори́м, моро́женым.\nВо втором отрывке упомянуты проводы зимы на Масленицу: блины, угощение и веселье перед Великим постом. Образ «поминки ей творим» передаёт народный обряд прощания с зимой.`,
      rule: `Старое ударение устанавливается по рифме; культурная реалия — по словам, связанным с обрядом.`,
    },
    68: {
      question: `Проанализируйте фрагмент И. С. Шмелёва о Масленице: объясните трудные слова, чувства героя, тему, типы речи и особенности выразительного чтения.`,
      answer: `Герой вспоминает Масленицу своего детства: блины, медовый запах, расписные сани, ледяные горы, лошадей, вечерние огни и народное веселье. Его чувства — радость, восхищение, тепло и грусть по ушедшему времени.\nТема — яркая Масленица в детской памяти. Основной тип речи — описание; вкрапления повествования передают движение катания и смену впечатлений. Редкие слова: горы́ — ледяные горки; изво́зчик — возница; квасни́чек — маленький сосуд для кваса; ко́злы — переднее сиденье экипажа; бу́беренцы — маленькие бубенчики.\nПри чтении логически выделяются слова «блины», «сани», «огни», «масленица»; перечисления читаются оживлённо, а заключение — медленнее и с оттенком воспоминания.`,
      rule: `Тип речи определяется по преобладающей задаче: показать признаки картины или последовательность действий.`,
    },
    69: {
      question: `Разберите значения слова «масленица» по словарю и тексту, затем приведите пословицы и объясните их смысл.`,
      answer: `В тексте «масленица» означает и народно-церковный праздник проводов зимы, и созданное для праздника чучело. Словарь также называет сырную неделю перед Великим постом, праздничное кушанье и переносный образ привольной, сытой жизни. Значение в каждом случае определяется контекстом.\nПословицы: «Не всё коту Масленица, будет и Великий пост» — удовольствие не длится вечно; «Без блинов не Масленица» — у праздника есть обязательный обычай; «Не житьё, а Масленица» — о весёлой и обеспеченной жизни; «Масленица — объедуха, деньгам приберуха» — угощения требуют больших расходов; «Хоть с себя что заложить, а Масленицу проводить» — праздник стремились отметить даже при бедности.`,
      rule: `Многозначное слово получает конкретное значение только в сочетании с окружающими словами.`,
    },
    70: {
      question: `Перепишите текст о Масленице, вставляя буквы, раскрывая скобки и расставляя знаки препинания.`,
      answer: `Масленица — древний славянский праздник, пришедший к нам из языческой культуры и сохранившийся после принятия христианства. По одной из версий, название «Масленица» возникло потому, что на этой неделе, по православному обычаю, мясо уже исключалось из пищи, а молочные продукты ещё можно было употреблять.\nМасленица — самый весёлый и сытный народный праздник, длящийся целую неделю. Народ его всегда любил и ласково называл «касаточка», «сахарные уста», «целовальница», «перепёлочка», «объедуха». Неотъемлемой частью праздника были катания на лошадях, на которых надевали самую лучшую сбрую. Так же широко, как и праздничная езда на лошадях, распространено было катание молодёжи с ледяных гор. Среди обычаев сельской молодёжи на Масленицу были и прыжки через костёр, и взятие снежного городка.`,
      rule: `Причастные обороты обособляются; названия и образные прозвища праздника заключаются в кавычки.`,
    },
    71: {
      question: `Перескажите учебный текст о трудных ударениях в глаголах прошедшего времени и составьте план с примерами.`,
      answer: `Текст относится к учебно-научной разновидности.\nПлан: 1) Подвижное ударение в прошедшем времени. 2) Ударение в форме женского рода. 3) Возвратные глаголы на -ся. 4) Глаголы на -ировать. 5) Изменение нормы во времени.\nОбычно в женском роде ударение переходит на окончание: жил — жила́, ждал — ждала́, лил — лила́, взял — взяла́. В возвратных формах ударение часто стоит на -ся: взяла́сь, дождала́сь. У глаголов на -ировать нужно проверять словарь: премирова́ть, пломбирова́ть; некоторые варианты меняются с развитием нормы.`,
      rule: `Ударение русского глагола подвижно, поэтому трудную форму проверяют отдельно, а не выводят механически из инфинитива.`,
    },
    72: {
      question: `Сравните произносительные пометы к глаголам «брать», «быть», «взять» в двух орфоэпических словарях и объясните различия.`,
      answer: `Современное произношение: беру́, берёт; бра́л, брала́, бра́ло, бра́ли. Буду, будет; был, была́, бы́ло, бы́ли. Возьму́, возьмёт; взял, взяла́, взя́ло, взя́ли. В женском роде ударение обычно переходит на окончание.\nСловари совпадают в основных формах, но могут по-разному оценивать старые или разговорные варианты: один допускает их с пометой «допустимо», другой признаёт устаревающими или неправильными. Это показывает изменение нормы: сначала варианты сосуществуют, затем один становится основным. В речи выбираем вариант без запретительной пометы и учитываем самое новое нормативное издание.`,
      rule: `Пометы «доп.», «устар.» и «неправ.» обозначают разные степени нормативности и не равны друг другу.`,
    },
    73: {
      question: `Расскажите по таблице об ударении в страдательных причастиях и составьте словосочетания с примерами.`,
      answer: `1) У некоторых причастий ударение всегда на основе: при́званный — при́зван, при́звана; и́збранный — и́збран. 2) В полной форме ударение может быть на основе, а в краткой — переходить: введённый — введён, введена́, введено́, введены́. 3) У причастий на -атый/-ятый ударение в краткой форме женского рода часто на окончании: на́чатый — на́чат, начата́; за́нятый — за́нят, занята́. 4) У форм от -бранный и -званный ударение сохраняется: со́бранный — со́брана, ото́званный — ото́звана, на́званный — на́звана.\nПримеры: при́званный специалист; введена́ в эксплуатацию; начата́я работа; занята́ ученицей парта; со́брана комиссия; на́звана причина.`,
      rule: `Полную и каждую краткую форму причастия проверяем отдельно, особенно женский род.`,
    },
    74: {
      question: `Расставьте ударение в причастиях, деепричастиях и наречиях и составьте с ними примеры.`,
      answer: `Причастия: балОванный ребёнок, зАгнутый край, зАнятый кабинет, занятА работой, зАпертая дверь, запертА изнутри, заселенА жильцами, избалОванный сын, налИвший воду, налитА в стакан, начАвший урок, нАчатый проект, начатА проверка, пОнявший правило, прИнятый закон, сОгнутый лист.\nДеепричастия: начАв работу, поднЯв руку, понЯв ошибку, прибЫв вовремя, создАв проект.\nНаречия: вОвремя прийти, добелА раскалить, дОверху наполнить, донЕльзя устать, дОнизу промокнуть, дОсуха вытереть, зАсветло вернуться, зАтемно выйти, красИвее оформить, подняться навЕрх, уехать надОлго, отлучиться ненадОлго.`,
      rule: `Ударение сверяется по орфоэпическому словарю; часть речи определяется по вопросу и роли в сочетании.`,
    },
    75: {
      question: `Проанализируйте два стихотворения Б. Л. Пастернака: названия, образы природы, причастия, деепричастия, наречия и ударение.`,
      answer: `«После дождя» показывает сначала бурю, затем тишину, солнечный луч и возникающую радугу. «Зазимки» — момент первого мороза, когда зима будто стесняется войти. Образы создают олицетворения: листва «толпится», зима «стоит, стыдясь», луч «залёг», погода «помораживает втайне»; сравнение «небосвод как зеркало на подзеркальник».\nПричастия: порванным, бревенчатой, мёрзлый, поставлен. Деепричастия: покатясь, стыдясь. Наречия: по-доброму, опрометью, вразноряд, ненадолго, поперёк, втайне. Значения: опрометью — стремительно; вразноряд — беспорядочно; втайне — скрыто.\nСлова читаются: о́прометью, вра́зноряд, ненадо́лго, поперёк, вта́йне, зази́мки. Проверка по словарю предотвращает перенос разговорного ударения.`,
      rule: `Выразительность создаётся сочетанием переносного значения, синтаксиса и звукового ритма.`,
    },
    76: {
      question: `Перепишите текст о русских лесах, вставляя буквы, раскрывая скобки и расставляя знаки препинания.`,
      answer: `Россию часто называют лесной страной, и это неслучайно. Леса покрывают её огромные пространства. При обилии дерева на Руси его всегда применяли для строительства и других целей очень рационально, с учётом свойств и качеств древесины. К примеру, дуб не боится воды. Поэтому из него делали срубы колодцев, сваи под здания. Всемирно известная колокольня «Иван Великий» Московского Кремля уже более 500 лет стоит на дубовых сваях. Пётр I строил корабли русского флота также из дуба и сосны. По своим качествам близка сосне лиственница, более устойчивая к сырости. Ель хуже других древесных пород сопротивлялась влаге: её предпочитали использовать для внутренней отделки дома. Из-за удивительных музыкальных способностей ель применяли для изготовления скрипок, гитар, других музыкальных инструментов. Осина обретает при высыхании дополнительные свойства: она быстро перестаёт гнить, и народ использовал это качество дерева. Тщательно топором вытёсывалась замечательная кровля, похожая на кольчугу.`,
      rule: `Не с наречием пишется слитно без противопоставления; обособляются сравнительные и причастные обороты.`,
    },
    77: {
      question: `Объясните различия паронимов «годовой», «годовалый», «годичный» по литературным и научному примерам.`,
      answer: `Годовой — относящийся к целому году или рассчитанный на год: годовой отчёт, годовой доход, «из годовых времён». Годовалый — проживший один год: годовалый ребёнок, годовалый щенок Рыжик. Годичный — продолжающийся год или возникающий за год: годичный курс, годичный отпуск, годичные кольца дерева.\nПравильно: годовая подписка, годовалый телёнок, годичный цикл обучения. Нельзя говорить «годовой щенок» в значении возраста или «годовалый отчёт».`,
      rule: `Паронимы похожи по форме, но различаются сочетаемостью и точным смыслом суффикса.`,
    },
    78: {
      question: `Разберите словарную статью о паронимах «эффективный» и «эффектный» и объясните разницу.`,
      answer: `Статья даёт заголовок, часть речи, толкование каждого слова, типичную сочетаемость и примеры. Эффективный — действенный, приводящий к нужному результату: эффективный метод, эффективная защита, эффективное лечение. Эффектный — производящий сильное впечатление внешним видом: эффектный костюм, эффектная внешность, эффектный выход.\nСравнение: эффективное выступление достигло цели и убедило слушателей; эффектное выступление было ярким и впечатляющим. Одно качество относится к результату, другое — к впечатлению.`,
      rule: `Значение паронима проверяется по существительному, с которым он обычно сочетается.`,
    },
    79: {
      question: `Составьте предложения с трудными созвучными словами из лингвистической заметки.`,
      answer: `Эскалатор поднял пассажиров на второй этаж. Экскаватор вырыл котлован. Новый аэропорт оборудован траволатором.\nЯ купил абонемент в бассейн. Абонент временно недоступен. Срок действия абонемента закончился.\nУдачный ответ принёс команде балл. Удачливый игрок снова победил. Эксперимент оказался удачным.\nМеня зовут Анна. Ребёнка назвали Петром. Учитель назвал имена победителей.`,
      rule: `Перед составлением предложения устанавливаем точное значение и управление каждого созвучного слова.`,
    },
    80: {
      question: `Составьте предложения с парами паронимов, показывая разницу их значений.`,
      answer: `Добрый человек помог соседу. Добротный дом простоит долго. Дружеский совет поддержал меня. Дружественная страна направила помощь. Эффектный плакат привлёк внимание. Эффективный план дал результат. Озеро отражает небо. Схема отображает движение поезда. Учитель проводит урок. Завод производит оборудование. Представьте нового ученика классу. Библиотека предоставит книгу. Мама одела малыша. Мальчик надел куртку. Подпись автора стоит под письмом. Роспись украшает стены храма.`,
      rule: `В каждой паре контекст должен раскрывать различие значения, а не просто грамматически допускать оба слова.`,
    }
  });

  Object.assign(solutions, {
    81: {
      question: `Изучите несплошной текст с рисунками о зимней одежде, озаглавьте его и объясните содержащуюся информацию и роль иллюстраций.`,
      answer: `Заголовок: «Как правильно одеться зимой». Информация: голову и уши защищает тёплая шапка; тепло сохраняет многослойная одежда; под верхнюю одежду надевают термобельё; руки защищают варежки; обувь должна быть тёплой, удобной и непромокаемой; шерстяные носки должны быть достаточно просторными, чтобы не нарушать кровообращение.\nРисунки делают инструкцию наглядной: нужный предмет узнаётся быстрее, а подпись сообщает его назначение. Такой несплошной текст воспринимать легче, чем сплошное описание, потому что сведения разделены на короткие блоки и связаны с изображениями.`,
      rule: `Несплошной текст читается по общей теме, изображениям, подписям и связям между блоками.`,
    },
    82: {
      question: `Подготовьте памятку о паронимах, которые часто вызывают ошибки в речи.`,
      answer: `Памятка «Не путай паронимы». Представить — показать, познакомить: представить гостя, представить доказательства. Предоставить — дать возможность или право: предоставить отпуск, предоставить слово. Надеть — что на себя: надеть пальто. Одеть — кого: одеть ребёнка. Эффектный — яркий внешне: эффектный костюм. Эффективный — результативный: эффективный метод. Адресат — получатель письма. Адресант — отправитель. Невежа — невоспитанный человек. Невежда — малообразованный человек.\nСовет: сначала мысленно объясни значение, затем проверь типичное управление и только после этого выбирай слово.`,
      rule: `Памятка должна давать краткое различие, управление и по одному ясному примеру.`,
    },
    83: {
      question: `Вставьте по смыслу формы глаголов «представить» или «предоставить».`,
      answer: `1) Брату предоставили квартиру. 2) Я предоставляю вам возможность самим решать такие вопросы. 3) Предоставляю вам слово. 4) Представляю вам мою сестру. 5) Отца представили к ордену. 6) Фильм был представлен на фестивале. 7) Артистка хорошо представила трагичную героиню. 8) Ты представляешь всю важность предстоящей встречи? 9) Моя родина представляет собой небольшой городок. 10) Делегация вологодских школьников представляла Россию.`,
      rule: `Предоставить — дать в распоряжение; представить — показать, познакомить, изобразить или быть представителем.`,
    },
    84: {
      question: `Прочитайте текст о тавтологии, выпишите неудачные сочетания и исправьте их.`,
      answer: `Тавтология — неоправданное повторение того же смысла однокоренными или близкими словами. Исправления: старый старик → старик или глубокий старик; молодой юноша → юноша; водянистая вода → безвкусная/разбавленная вода; сладкий сахар → сахар; холодный лёд → лёд; разувать обувь → снимать обувь или разуваться; сегодняшний день → сегодня или нынешний день; главный лейтмотив → лейтмотив.\nИсправленные предложения: «Я разуюсь». «Отец разул ребёнка». «Каков прогноз погоды на сегодня?» Тавтология допустима как художественный приём, если повтор намеренно усиливает мысль.`,
      rule: `Убираем слово, которое дублирует смысл, не меняя содержания предложения.`,
    },
    85: {
      question: `Исправьте ошибки, возникшие из-за смешения паронимов.`,
      answer: `1) Утверждая документацию, директор ставит на ней свою подпись. 2) Обмёрзшие стёкла окошек едва рассеивают тусклый свет. 3) В кормушке за окном кухни пировал воробей. 4) При решении проблемы потребовались экскурсы в математику и биологию. 5) Зима покрыла землю снегом. 6) На мебель были надеты чехлы, и это придавало комнате нежилой вид. 7) После завтрака он одел сына и вышел с ним на улицу. 8) У лисы пушистый хвост. 9) Самолёты значительно сократили путь от Камчатки до Якутска. 10) В новом учебнике глава «Десятичные дроби» не претерпела существенных изменений. 11) Насекомые обладают хорошо развитым обонянием.`,
      rule: `Пароним выбирается по значению и устойчивой сочетаемости: подпись, обмёрзший, экскурс, пушистый, претерпеть, обоняние.`,
    },
    86: {
      question: `Выберите подходящий пароним в двенадцати предложениях и отметьте случаи возможных вариантов.`,
      answer: `1) Состав встал. 2) В работах художников и скульпторов отразился труд, быт и отдых забайкальцев. 3) Я припоминаю лицо этого человека. 4) Молодой актёр играет главную роль. 5) Назира усиленно готовится к экзаменам. 6) Большой выбор красивой и практичной обуви. 7) Группа школьников пришла в музей на лекцию. 8) Болельщики собрались в вестибюле. 9) В порту судно стало на якорь. 10) Перед подвигом защитников Отечества мы преклоняем голову. 11) Чёрные цвета вперемежку с бурыми и белыми полосками делают оперение селезня очень эффектным. 12) Новый ученик был представлен классу.\nВ отдельных контекстах возможны «состав стал/встал» и «школьники пришли/зашли», но оттенок различается: стал — остановился, встал — прекратил движение; зашли — вошли ненадолго или по пути.`,
      rule: `При двух грамматически возможных словах учитываем оттенок действия и контекст.`,
    },
    87: {
      question: `Объясните различия слов «висящий — висючий» и «горящий — горячий», составьте сочетания и предложения.`,
      answer: `Висящий — находящийся на весу: висящая лампа, висящий мост. Висючий — свисающий вниз, обычно о длинных ушах или декоративных растениях; слово разговорное: висючие уши собаки. Горящий — охваченный огнём или сильно увлечённый: горящий костёр, горящие глаза. Горячий — имеющий высокую температуру или пылкий: горячий чай, горячий спор.\nПримеры: Над столом висит висящий светильник. У щенка висючие уши. Пожарные потушили горящий сарай. Я осторожно поставил горячую чашку.`,
      rule: `Паронимы различаются значением признака и стилистической окраской.`,
    },
    88: {
      question: `Перепишите текст Л. Успенского о языке, раскрывая скобки, вставляя буквы и знаки препинания.`,
      answer: `С самого раннего детства и до глубокой старости вся жизнь человека неразрывно связана с языком. Ребёнок ещё не научился как следует говорить, а его чистый слух уже ловит журчание бабушкиных сказок, материнской колыбельной песенки. Но ведь сказки и прибаутки — это язык.\nПодросток идёт в школу. Юноша шагает в институт или в университет. Целое море слов, шумный океан речи подхватывает его там, за широкими дверями. Сквозь живые беседы учителей, сквозь страницы сотен книг впервые видится ему отражённая в слове необъятно сложная Вселенная. Через слово он впервые узнаёт о том, что ещё не видели, а возможно, и никогда не увидят его глаза...\nВсё, что люди совершают в мире действительно человеческого, совершается при помощи языка. Нельзя без него работать согласованно, совместно с другими. Без его посредства немыслимо ни на шаг двинуть вперёд науку, технику, ремёсла, искусство — жизнь.`,
      rule: `Не с глаголами пишется раздельно, а однородные обстоятельства и части сложного предложения разделяются запятыми.`,
    },
    89: {
      question: `Проанализируйте формы слов в отрывках из «Евгения Онегина»: соответствуют ли они современной норме и к каким частям речи относятся?`,
      answer: `Петербург показан как город, который не спит: после ночного бала Онегин едет домой, а купцы, разносчики и извозчики уже начинают рабочий день. Формы «в постелю» и «обратя» были допустимы в пушкинскую эпоху, но современная норма: «в постель», «обратив». «Постелю» — старая падежная форма существительного, «обратя» — старый вариант деепричастия.\n«Полусонный», «неугомонный», «пробуждён» — прилагательные/краткое причастие; «утомлённый», «блаженной» — причастие и прилагательное; «забав и роскоши дитя» — поэтическое приложение. Нормы исторически меняются, поэтому формы классического текста нельзя исправлять в цитате, но в собственной современной речи используются новые варианты.`,
      rule: `Форму оцениваем с учётом эпохи: авторская цитата сохраняется, современный эквивалент объясняется отдельно.`,
    },
    90: {
      question: `Сравните глаголы «поднимать» и «подымать» по словарной статье, определите их стилистическую роль и составьте примеры.`,
      answer: `Поднимать — нейтральный основной вариант: поднимать флаг, поднимать вопрос, поднимать штангу, поднимать команду в атаку. Подымать — разговорный вариант, чаще о простом физическом действии: «Не подымай тяжёлый чемодан», «Подымается ветер». В официальных и устойчивых сочетаниях замена невозможна: правильно «вопрос не поднимается», «поднимать знамя».\nСпортивные примеры: Атлет поднимает штангу. Капитан поднимает боевой дух команды. Разговорно: «Не подымай гирю без разминки». Основным следует считать «поднимать», потому что оно нейтрально и употребляется во всех стилях.`,
      rule: `Стилистические варианты различаются не смыслом, а сферой употребления и сочетаемостью.`,
    },
    91: {
      question: `Составьте приглашения, правильно употребив повелительные формы глаголов «ехать» и «пойти».`,
      answer: `Друзья, поезжайте со мной по городам Золотого кольца России! Поезжай со мной во Владимир и Суздаль — увидим древние соборы и музеи.\nПойдём сегодня в кино! Пойдите с нами на новый фильм, пожалуйста.\nНормативные формы: поезжай, поезжайте; пойди, пойдите, пойдём. Формы «ехай», «едь» и «едьтe» в литературной речи не употребляются.`,
      rule: `У глагола «ехать» повелительная форма образуется от другой основы: поезжай/поезжайте.`,
    },
    92: {
      question: `Образуйте нормативные формы 3-го лица множественного числа от данных глаголов.`,
      answer: `Капать — капают; сыпать — сыплют; дремать — дремлют; мяукать — мяукают; полоскать — полощут; махать — машут; трепать — треплют; плакать — плачут; щипать — щиплют.\nПримеры: С крыши капают капли. Дети сыплют корм. Кошки мяукают. Прачки полощут бельё. Флаги машут на ветру. Ребята щиплют траву. Разговорные варианты «сыпят», «полоскают», «махают» встречаются, но в образцовой литературной речи предпочтительны указанные формы.`,
      rule: `Форма 3-го лица зависит от типа спряжения и чередования согласных, поэтому трудные глаголы проверяются по словарю.`,
    },
    93: {
      question: `Образуйте, если возможно, форму 1-го лица единственного числа и объясните отсутствие некоторых форм.`,
      answer: `Затмить — затмлю; капать — капаю; дерзить — дерзю; блестеть — блещу; жаждать — жажду; брести — бреду.\nУ глаголов «победить» и «очутиться» простые формы 1-го лица воспринимаются как ненормативные или неблагозвучные: нельзя «побежу», «победю», грубо неправильно «очучусь». Используются описания: я смогу победить, я одержу победу; я смогу очутиться, я окажусь.`,
      rule: `Если нормативная личная форма не образуется, значение передаётся описательным сочетанием.`,
    },
    94: {
      question: `Поставьте данные глаголы в форму мужского рода прошедшего времени.`,
      answer: `Зябнуть — зяб (допустимо зябнул); меркнуть — мерк; исчезнуть — исчез; остыть — остыл; заворожить — заворожил; завораживать — завораживал; увезти — увёз; кивнуть — кивнул; прыгнуть — прыгнул; сохнуть — сох (допустимо сохнул); закипать — закипал; закипеть — закипел.`,
      rule: `У части глаголов на -нуть суффикс в прошедшем времени выпадает, у других сохраняется; вариант проверяется словарём.`,
    },
    95: {
      question: `Сравните употребление форм «брызжет» и «брызгает» в трёх стихотворных отрывках и сформулируйте различие.`,
      answer: `В первом и третьем отрывках «брызжет» означает «ярко разлетается, выбрасывает брызги или искры» и создаёт образ стихийного движения: осень брызжет серебром, волна брызжет в глаза. Во втором «брызгая водой из луж» обозначает повторное действие при ходьбе, когда кто-то разбрасывает капли.\nФормы могут быть вариантами, но оттенок различается: «брызжет» чаще о том, что само сильно испускает мелкие капли; «брызгает» — о повторном или направленном действии. Примеры: Фонтан брызжет на солнце. Ребёнок брызгает водой на друзей.`,
      rule: `Близкие формы сравниваются по субъекту действия, его направленности и контекстному оттенку.`,
    },
    96: {
      question: `Озаглавьте и перескажите текст о вариантах образования глаголов несовершенного вида, разделите примеры на группы и добавьте свои.`,
      answer: `Заголовок: «Чередование о/а при образовании несовершенного вида».\n1) Безударное о обязательно переходит в ударное а: приколо́ть — прикола́чивать, разброса́ть — разбра́сывать. 2) Ударное о также может переходить в а: застро́ить — застра́ивать, затро́нуть — затра́гивать, усво́ить — усва́ивать. 3) В ряде глаголов о сохраняется: обескро́вить — обескро́вливать, приуро́чить — приуро́чивать. 4) Существуют книжный вариант с о и разговорный с а: обусло́вливать — обусла́вливать, сосредото́чивать — сосредота́чивать, уполномо́чивать — уполнома́чивать.\nПримеры: заморо́зить — замора́живать; удво́ить — удва́ивать; опоро́чить — опоро́чивать.`,
      rule: `Чередование зависит не от одного универсального правила: словарная норма закрепляет конкретную пару.`,
    },
    97: {
      question: `Проанализируйте научно-популярный текст об изменении климата: тема, стиль, заголовок, формы глаголов и значения терминов.`,
      answer: `Тема — разрушение естественных экосистем человеком как причина глобального изменения климата. Стиль — научно-популярный: есть термины, причинно-следственные связи и доступное объяснение. Заголовок: «Разрушение экосистем и климат». Ключевые слова: климат, экосистема, лес, океан, биосфера, биологические потребности.\nВыделенное «происходящих» имеет начальную форму «происходить». Это нормативный глагол несовершенного вида, соотносимый с «произойти»; его образование закреплено исторически и не сводится к продуктивному чередованию о/а. Экосистема — сообщество организмов и среда их обитания как единое целое; биосфера — оболочка Земли, заселённая живыми организмами; сведение лесов — вырубка и уничтожение лесного покрова.`,
      rule: `Научный термин объясняется точно, а грамматическая форма проверяется по начальной форме и видовой паре.`,
    },
    98: {
      question: `Проанализируйте рассказ В. Е. Ардова «Суконный язык»: цель авторской улыбки, правильность причастий и смысл названия.`,
      answer: `Автор высмеивает канцелярскую тяжеловесность. В объявлении вместо простого «За хождение по траве, повреждение растений, мусор и выгул животных взимается штраф» нагромождены причастия «ходящие», «вырастающей», «пристающие», «подставляющие», «загрязняющих», а концовка «являются штрафующимися» грамматически и логически неверна: нарушители не штрафуют себя, а подвергаются штрафу.\nВ «статье об искусстве» цепочки «чувствующий, осмысливающий, выражающий...» формально возможны, но однообразны, местами нарушают связь слов и делают мысль непонятной.\n«Суконный язык» — серый, грубый, шаблонный бюрократический стиль, похожий на простую грубую ткань — сукно. Смех направлен против многословия и стремления казаться учёным.`,
      rule: `Грамматически возможная форма может быть стилистически плохой, если затемняет смысл и перегружает фразу.`,
    },
    99: {
      question: `Образуйте страдательные причастия прошедшего времени и запишите рядом исходные глаголы.`,
      answer: `Выпаять — выпаянный; выпоить — выпоенный; выкушать — выкушанный; выкусить — выкушенный; выметать петлю — выметанный; вымести сор — выметенный; перекачать — перекачанный; перекатить — перекатанный; развенчать — развенчанный; развинтить — развинченный; разбросать — разбросанный.`,
      rule: `Суффикс причастия и чередование согласных зависят от основы инфинитива и формы прошедшего времени.`,
    },
    100: {
      question: `Объясните пословицы и особенности старых деепричастных форм; укажите современные соответствия.`,
      answer: `«Давши слово, крепись» — обещание нужно выполнять. «Снявши голову, по волосам не плачут» — после большой потери поздно жалеть о малой. «Говоря, подумай, садясь, осмотрись» — прежде действия оцени последствия. «Не учась, и лаптя не сплетёшь» — без учения нельзя овладеть даже простым ремеслом.\nФормы «давши», «снявши» образованы старым суффиксом -вши; современно нейтрально: дав, сняв. «Говоря», «садясь», «не учась» являются обычными современными деепричастиями. Формы на -вши сохраняются в пословицах и разговорной речи, но в нейтральном тексте предпочтительны формы на -в.`,
      rule: `Пословица сохраняет старую грамматическую форму как часть неизменного устойчивого выражения.`,
    }
  });

  Object.assign(solutions, {
    101: {
      question: `Исправьте ошибки в формах сравнительной и превосходной степени и запишите нормативные варианты.`,
      answer: `Правильно: выглядел красивее (или: выглядел более красиво); написал диктант хуже; сильнейший ученик в классе (или: самый сильный ученик в классе); высочайшее мастерство (или: самое высокое мастерство).\nОшибки возникли из-за соединения простой и составной форм: нельзя говорить «более красивее» и «самое высочайшее». Формы «хужее» и «наисильнейший» здесь также ненормативны.`,
      rule: `Простую и составную степени сравнения не смешивают: либо «красивее», либо «более красивый»; либо «высочайший», либо «самый высокий».`,
    },
    102: {
      question: `Спишите текст об исторической ценности личных писем, раскрывая скобки, вставляя пропущенные буквы и расставляя знаки препинания.`,
      answer: `История многократно показала, как факты и документы, казавшиеся ясными, приобретали с течением времени значение общее. Судить не нам, современникам. Сохранённое вами письмо приятеля может впоследствии оказаться единственным письменным свидетельством важного, но плохо зафиксированного события. Во всём этом нет нимало преувеличения — именно таким непредугаданным заранее путём часто письмо становится ценнейшим историческим источником. Архивный опыт убеждает: к сожалению, в огромном большинстве случаев люди совершенно не знают себе цены и ценности хранящихся у них в доме старинных документов.`,
      rule: `Причастный оборот после определяемого слова обособляется; однородные и противопоставленные определения разделяются запятыми; пояснение после слов со значением сообщения можно оформить двоеточием.`,
    },
    103: {
      question: `Объясните совет Владимира Мономаха не пропускать человека без приветствия и доброго слова. Приведите примеры добрых слов и опишите доброго человека.`,
      answer: `Совет означает: при встрече нужно замечать человека, приветствовать его и обращаться к нему уважительно. Доброе слово — искреннее приветствие, благодарность, пожелание, поддержка или извинение: «Здравствуйте!», «Спасибо», «Будьте добры», «Рад вас видеть», «Не огорчайтесь, я помогу», «Простите, пожалуйста».\nДоброго человека можно назвать доброжелательным, отзывчивым, внимательным и тактичным. Он первым здоровается, выслушивает собеседника, не перебивает, помогает делом и словом, не унижает и не отвечает грубостью.`,
      rule: `Русский речевой этикет требует приветствия, уважительного обращения и выбора слов, поддерживающих достоинство собеседника.`,
    },
    104: {
      question: `Проанализируйте фрагмент повести М. Горького «Детство»: чувства Алёши и бабушки, особенности её речи, смысл сравнения с песней, отличие от речи матери и формы обращения.`,
      answer: `Алёша испытывает к бабушке любовь, доверие и восхищение: рядом с ней ему тепло и интересно. Бабушка отвечает нежностью и заботой, употребляет ласковые обращения и разговорно-народные слова. Её речь напевна, образна, ритмична и эмоциональна, поэтому герой говорит, что она «точно поёт»: чем дольше она рассказывает, тем складнее и музыкальнее звучат слова.\nРазговорные и устаревающие слова вроде «ась», «чай», «али», «поди», «больно» передают живую народную речь и время действия. Речь матери более сдержанная, строгая и отдалённая, речь бабушки — сердечная и ласковая. Формы обращения: «милый», «голубь», «батюшка»; они выражают доброжелательность и близость. При чтении нужны мягкая интонация, неторопливый темп и смысловое выделение ласковых слов.`,
      rule: `Речевой портрет героя создают лексика, обращения, интонация, ритм фраз и авторская оценка речи.`,
    },
    105: {
      question: `Определите, какая традиция семейного речевого общения отражена в старинной свадебной песне и в поясняющем тексте. Подтвердите ответ примерами.`,
      answer: `Отражена традиция почтительного родственного обращения к семье мужа. Невеста собирается называть свёкра «батюшком», свекровь «маменькой», деверей «братцами», а золовок «сестрицами». Такие обращения вводили нового человека в семью и одновременно выражали уважение и душевную близость.\nУменьшительно-ласкательные формы «свёкорушко», «свекровушка», «братишки», «сестрицы» усиливают доброжелательный оттенок. Сегодня родителей супруга иногда по-прежнему называют мамой и папой, но нередко обращаются к ним по имени и отчеству.`,
      rule: `Традиционные термины родства и ласкательные суффиксы показывают степень близости и уважения между членами семьи.`,
    },
    106: {
      question: `Проанализируйте письмо Д. С. Лихачёва «Быть весёлым, но не быть смешным»: назовите правила общения, оцените их пользу и подберите пословицы.`,
      answer: `Главные правила: не мешать другим и не шуметь; уметь слушать и помогать; шутить к месту и не утомлять людей повторёнными шутками; не стараться постоянно быть в центре внимания; соблюдать меру в речи, одежде и поведении; не стыдиться особенностей речи или застенчивости; сохранять скромность и достоинство. Эти советы полезны в классе, дома, в гостях, в переписке и любом разговоре.\nПодходящие пословицы: «Слово — серебро, молчание — золото»; «Умей вовремя сказать, вовремя смолчать»; «Не спеши языком, торопись делом»; «Короткую речь слушать хорошо»; «Смех хорош, когда он к месту».`,
      rule: `Тактичность проявляется в чувстве меры, внимании к собеседнику, умении слушать и соотносить своё поведение с ситуацией.`,
    },
    107: {
      question: `Спишите текст Д. С. Лихачёва о заботе и сострадании, вставляя пропущенные буквы и расставляя знаки препинания.`,
      answer: `Забота объединяет людей, крепит память о прошлом и направлена целиком на будущее. Это не само чувство — это конкретное проявление чувства любви, дружбы и патриотизма. Человек должен быть заботлив. Незаботливый или беззаботный человек, скорее всего, человек недобрый и не любящий никого.\nНравственности в высшей степени свойственно чувство сострадания. В сострадании есть сознание своего единства с человечеством и миром (не только людьми, народами, но и с животными, растениями, природой и т. д.). Чувство сострадания (или что-то близкое ему) заставляет нас бороться за памятники культуры, за их сохранение, за их продление, за уважение к памяти. В сострадании есть сознание своего единства с другими людьми и с нацией, народом, страной, Вселенной. Именно поэтому забытое понятие сострадания требует своего полного возрождения и развития.`,
      rule: `Вводное сочетание «скорее всего» обособляется; пояснение присоединяется тире; однородные члены разделяются запятыми.`,
    },
    108: {
      question: `Опишите ситуации употребления приведённых форм русского речевого этикета и укажите выражения, почти вышедшие из современного употребления.`,
      answer: `Приветствие: «Здравствуйте», «Здорово живёте», «Моё почтение», «Позвольте честь заявить». Встреча гостя и приглашение: «Добро пожаловать», «Милости просим». Пожелание за столом: «Приятного аппетита», «Ангел за трапезой», «Хлеб да соль», «Чай да сахар». Пожелание в труде и промысле: «Бог помочь», «Море под кормилицу». Благодарность: «Спасибо», «Благодарю вас», «Позвольте выразить вам мою сердечную признательность». Прощание: «Будьте здоровы», «До новых встреч», «Пока». Завершение письма: «С искренним уважением...», «Ваш покорнейший слуга...».\nАрхаичны или сильно устарели: «позвольте честь заявить», «ангел за трапезой», «беленько тебе», «море под кормилицу», «спаси тебя Христос», «ваш покорнейший слуга»; выражения «здорово живёте», «моё почтение», «хлеб да соль», «чай да сахар», «Бог помочь» употребляются ограниченно или стилизованно.`,
      rule: `Формула этикета выбирается по ситуации, отношениям собеседников, степени официальности и исторической эпохе.`,
    },
    109: {
      question: `Проанализируйте словарную статью А. Г. Балакая о формуле утешения «Есть о чём горевать!» и запишите известные формулы поддержки в трудной ситуации.`,
      answer: `Статья сообщает значение формулы, её речевую функцию и даёт пример из художественного текста. «Есть о чём горевать (кручиниться, плакать)!» — не буквальное согласие, а утешение: говорящий убеждает собеседника, что случившееся не представляет большой беды. Так словарь помогает увидеть скрытый смысл этикетной реплики и не понимать её дословно.\nФормулы утешения: «Не огорчайся, всё поправимо»; «Я рядом и готов помочь»; «Держись, пожалуйста»; «Всё обязательно наладится»; «Мне очень жаль, что это случилось»; «Если хочешь, давай поговорим».`,
      rule: `Этикетная формула может иметь переносный прагматический смысл, который раскрывается только в ситуации общения.`,
    },
    110: {
      question: `По фрагменту «Писем о добром и прекрасном» Д. С. Лихачёва сформулируйте правила общения, назовите важные качества воспитанного человека и составьте руководство для сверстников.`,
      answer: `Лихачёв советует не мешать другим и не шуметь, не утомлять людей беспрерывными шутками, соблюдать сдержанность в манерах и одежде, уважать чужое мнение, уметь сглаживать конфликт и добровольно уступать, признавать собственные слабости и промахи. Главные качества воспитанного человека — уважительность, такт, скромность, доброжелательность, самообладание и ответственность. Я согласен: такие качества помогают сохранить достоинство обоих собеседников и избежать ненужных ссор.\nПравила современного речевого поведения: 1) здоровайся и обращайся уважительно; 2) слушай не перебивая; 3) говори ясно и спокойно; 4) не высмеивай собеседника; 5) не пересказывай чужие шутки и тайны без разрешения; 6) спорь с мыслью, а не с человеком; 7) умей извиниться и поблагодарить; 8) в переписке не пиши оскорблений и не злоупотребляй заглавными буквами; 9) проверяй сообщение перед отправкой; 10) помни, что хорошие манеры выражают бережное отношение к людям и миру.`,
      rule: `Воспитанность — не набор внешних жестов, а устойчивое уважительное отношение к человеку, проявляющееся в речи и поступках.`,
    },
    111: {
      question: `Докажите, что рисунки изображают средства невербального общения, и объясните связь мимики с нормами этикета и национальными традициями.`,
      answer: `На рисунках смысл передаётся без слов — выражением глаз, бровей и рта. Поэтому это невербальное общение. Показаны нейтральность, враждебность, радость, сильный гнев, недовольство, простодушие, усталость, лёгкая злость, притворная радость, расстройство, скепсис и печаль.\nС точки зрения этикета открытая доброжелательная мимика помогает установить контакт; демонстративное раздражение, презрение или скука могут обидеть собеседника. Мимика частично универсальна, но допустимая сила выражения эмоций, частота улыбки и зрительного контакта зависят от культуры. Значит, национальные традиции могут влиять на то, как выражение лица воспринимается, хотя основные эмоции узнаваемы многими народами.`,
      rule: `Невербальные знаки дополняют слова, но их значение нужно оценивать вместе с ситуацией и культурными нормами.`,
    },
    112: {
      question: `Проанализируйте фрагмент рассказа К. Г. Паустовского «Бакенщик»: объясните название, изменение отношения мальчиков к Семёну, слово «многоречивый» и смысл заключительных слов; сформулируйте тему рассуждения.`,
      answer: `Рассказ назван по занятию Семёна: бакенщик зажигает и обслуживает речные бакены, помогая судам идти безопасным путём. Сначала мальчики считают его ворчливым, потому что он повторяет, что людям «всё мало», ругается и поучает. Во время разговора отношение меняется: Семён заставляет их увидеть красоту родной природы и объясняет любовь к Родине через внимательное отношение к каждой траве и цветку. В конце мальчик уже говорит: «Совсем понятный».\n«Многоречивый» — говорящий много и подробно. Семён действительно сразу заводит длинный разговор, задаёт вопросы, приводит примеры о клевере, медунице, сон-траве и купене.\nФинал «Уважению учить к родной земле. Без этого человек — не человек, а труха!» означает: любовь к Родине начинается с умения видеть, беречь и уважать её природу; без духовной связи с родной землёй человек внутренне пуст. Тема сочинения: «Почему любовь к Родине начинается с внимания к малому». Тезис: патриотизм доказывается не громкими словами, а заботой о земле, памяти, людях и природе.`,
      rule: `Изменение отношения героя подтверждается его репликами до и после важного разговора, а смысл финала раскрывается через основную мысль всего эпизода.`,
    },
    113: {
      question: `Подготовьте краткую презентацию об исторических лицах и деятелях культуры, чьи судьбы связаны с Коломной: Д. Донском, А. Алябьеве, А. Ахматовой, И. Лажечникове и Б. Пильняке.`,
      answer: `Дмитрий Донской связан с Коломной как князь, собравший здесь русские полки перед походом на Куликово поле в 1380 году; здесь он венчался с Евдокией, а в городе установлен его памятник.\nКомпозитор Александр Алябьев отбывал ссылку в Коломне в 1842–1843 годах. Он известен прежде всего как автор романса «Соловей» на стихи А. Дельвига.\nАнна Ахматова побывала в Коломне 16 июля 1936 года: осматривала город и пыталась найти дом своего друга Бориса Пильняка; поездка и пребывание в окрестностях Коломны отразились в её стихах.\nИван Лажечников родился в Коломне и провёл здесь детство; с его именем связаны городская усадьба-музей и память об авторе исторических романов «Ледяной дом» и «Последний Новик».\nБорис Пильняк жил в Коломне в 1917–1924 годах и создавал здесь прозу; сохранился дом, связанный с писателем.\nСтруктура презентации: 1) Коломна на карте истории; 2) Дмитрий Донской; 3) писатели и композитор; 4) памятные места; 5) вывод о городе как культурном центре.`,
      rule: `В исследовательской презентации каждое имя связывают с конкретным событием, местом, произведением или памятником и отделяют проверенный факт от предположения.`,
    },
    114: {
      question: `Проанализируйте речевой этикет Матрёны и её гостя во фрагменте рассказа А. И. Солженицына «Матрёнин двор» и охарактеризуйте речевую манеру героини.`,
      answer: `Оба героя следуют традиции уважительного общения. Рассказчик каждое утро первым говорит: «Доброе утро, Матрёна Васильевна!», обращаясь по имени и отчеству. Матрёна отвечает тёплым домашним мурчанием: «М-м-м... также и вам!» — и заботливо сообщает о завтраке.\nЕё речь простая, народная, мягкая и напевная. В ней есть деревенские слова и произношение: «картовь», «суп картонный», «необлупленная», «приспе́ел». Сначала рассказчику они непривычны, но песенная интонация и искренность вызывают у него умиление: после русских романсов он признаёт её речь «по-нашему». Речевой этикет проявляется не только в формулах приветствия, но и во взаимной доброжелательности.`,
      rule: `Речевая манера складывается из словаря, произношения, интонации и устойчивых формул общения; её оценка зависит от отношения между героями.`,
    },
    115: {
      question: `Выполните орфографический и пунктуационный практикум: восстановите текст Д. Гранина о милосердии.`,
      answer: `А нравственность состоит из конкретных вещей — из определённых свойств личности. Одно из таких чувств — милосердие. Термин несколько устаревший, непопулярный сегодня и даже как будто отторгнутый нашей жизнью. Нечто свойственное лишь прежним временам. «Сестра милосердия», «брат милосердия» — даже словарь даёт их как «устар.», то есть устаревшие понятия.\nУверен, что человек рождается со способностью откликаться на чужую боль. Думаю, что это прирождённое, данное нам вместе с инстинктами, с душой.`,
      rule: `Краткое пояснение присоединяется тире; однородные определения разделяются запятыми; придаточное с «что» отделяется запятой; «как будто» пишется раздельно.`,
    },
    116: {
      question: `Раскройте смысл ключевых слов раздела «Культура речи» и объясните мысль В. В. Виноградова из эпиграфа.`,
      answer: `Орфоэпические нормы регулируют произношение и ударение, в том числе в глагольных формах и наречиях. Лексические нормы требуют точного употребления слов и различения паронимов. Грамматические нормы определяют правильное образование и сочетание форм, включая глаголы, причастия, деепричастия и наречия. Русская этикетная речевая манера общения — это выбор уместных приветствий, обращений, благодарностей, извинений и других формул. Невербальное общение передаёт отношение мимикой, жестами, позой и взглядом.\nМысль Виноградова означает: культура речи соединяет правильность и содержательность. Недостаточно не делать ошибок — нужно точно, ясно, выразительно и уместно передавать мысль, уважая собеседника и богатство литературного языка.`,
      rule: `Культура речи включает нормативность, точность, ясность, выразительность, уместность и этичность высказывания.`,
    },
    117: {
      question: `Проанализируйте два эпизода из «Звёздного билета» В. П. Аксёнова: повод и ирония комплиментов, возможные неироничные варианты, время действия, устаревшее обращение и роль отсылки к Пушкину.`,
      answer: `В первой ситуации Галя просит взять её в поездку. Димка говорит, что с её «глазками» и «фигуркой» она поступит в театральный институт. Формально это похвала внешности, но в ней слышатся снисходительность и попытка отвлечь девушку от серьёзного разговора; поэтому Галя иронически объявляет: «Он сделал мне комплимент!». Искренний вариант: «Галя, ты талантливая и целеустремлённая; думаю, из тебя получится хорошая актриса».\nВо второй ситуации мать называет фантастический план «точным, детальным» и «прекрасным». Это ирония: в плане нет реального расчёта, зато есть сказочная «золотая рыбка». Искренний вариант: «План смелый; мне нравится, что вы продумали маршрут, но давайте проверим, насколько он выполним».\nСобытия относятся к советскому времени: упоминаются Ленинград, театральный институт и рыболовецкий колхоз. Обращение «Димче» стилизовано под старую звательную форму. Напоминание о сказке Пушкина и золотой рыбке подчёркивает несбыточность желаний героев. Поводом для комплимента могут быть поступок, умение, труд, внешность или черта характера, но похвала должна быть конкретной и искренней.`,
      rule: `Иронический комплимент внешне похож на похвалу, но контекст и интонация сообщают противоположную оценку.`,
    },
    118: {
      question: `Определите языковые приёмы в трёх комплиментах из русской литературы.`,
      answer: `1. Ф. Достоевский: «Вы прекрасны, а не красны!» — игра близкими по звучанию словами «красны» и «прекрасны», противопоставление и усиление значения.\n2. В. Шукшин: «Да она просто красавица! Просто зоренька ясная» — восклицание, повтор слова «просто» и народно-поэтическая метафора-сравнение с ясной зарёй.\n3. Л. Толстой: «Не все, потому что вас там не будет» — скрытое противопоставление и смысловой парадокс: без собеседницы нельзя сказать, что на балу будут все красивые женщины. Повтор «не все» усиливает похвалу.`,
      rule: `Комплимент становится выразительным благодаря игре слов, метафоре, повтору, противопоставлению и неожиданному логическому повороту.`,
    },
    119: {
      question: `Проанализируйте самохарактеристику школьника: выделите разговорные выражения, подберите синонимичный фразеологизм, оцените названные качества, дополните их и объясните народное отношение к хвастовству.`,
      answer: `Школьная разговорная речь: «по химии отличник», «весь класс контрольные сдувает», «четыре варианта за полчаса отщёлкать», «ума не приложу». Синоним к «ума не приложу» — «уму непостижимо».\nГерой действительно называет способности: хорошо знает химию, быстро решает задания, помогает одноклассникам. Но делает это хвастливо и считает достоинством списывание всего класса. Уместнее было бы сказать: «Я хорошо успеваю по химии, быстро решаю задачи и могу объяснить материал одноклассникам». Можно добавить ответственность, честность, трудолюбие и готовность работать в команде.\nНарод осуждает хвастовство, потому что человека должны оценивать по делам: «Хвастать — не косить: спина не болит»; «Коли хорошо, так не хвастай: тебя и так заметят»; «Хвастун да врун одного поля ягоды». Личная страница в социальной сети может быть краткой самохарактеристикой, но отражает действительность лишь частично: человек сам отбирает выгодные сведения и фотографии.`,
      rule: `Самопрезентация должна быть правдивой, конкретной и уместной; достоинства лучше подтверждать поступками и результатами.`,
    },
    120: {
      question: `Проанализируйте отрывок из басни И. А. Крылова «Лжец»: какие качества высмеиваются, что означает выделенное выражение и чем честная самопрезентация отличается от хвастовства.`,
      answer: `В басне высмеиваются ложь, хвастовство, тщеславие и стремление поразить слушателя выдумками. Выражение «к былям небылиц без счёту прилыгал» означает: к правдивым рассказам герой добавил бесчисленное множество выдуманных событий.\nКратко представлять себя приходится при знакомстве с новым классом или кружком, на конкурсе, собеседовании, в анкете и профиле. Честная самопрезентация сообщает проверяемые факты: имя, интересы, опыт, сильные стороны и цель. Хвастовство преувеличивает достоинства и обещает невозможное. Страница в социальной сети может служить характеристикой лишь условно: она показывает выбранную владельцем часть жизни и не всегда совпадает с реальностью.`,
      rule: `Хорошая самопрезентация опирается на факты и меру; басня разоблачает расхождение между громкими словами и правдой.`,
    }
  });

  Object.assign(solutions, {
    121: {
      question: `Проанализируйте воспоминания А. Н. Вертинского о России: объясните выделенные слова, смысл комплимента стране и напишите письмо человеку, ещё не видевшему Россию.`,
      answer: `Индустриальный — связанный с развитой промышленностью; конкурировать — соперничать на равных; величие — выдающееся значение и мощь; машинистка — работница, печатавшая тексты на пишущей машинке. Слова английской машинистки «Я работаю, чтобы жить, а вы — живёте, чтобы работать!» становятся комплиментом советским людям: она замечает их трудолюбие, энергию и увлечённость общим делом. Подходящие пословицы: «Без труда не вытащишь и рыбку из пруда», «Дело мастера боится», «Терпение и труд всё перетрут».\nПисьмо: «Дорогой друг! Россия поражает масштабом, природным и культурным разнообразием. Здесь рядом существуют древние города, современные научные центры, северные моря, степи, тайга и горы. Особенно я ценю людей, которые умеют объединяться, много работать, беречь память и помогать друг другу. Чтобы почувствовать страну, стоит увидеть не только столицу, но и малые города, музеи, заповедники и обычную повседневную жизнь».`,
      rule: `Смысл оценочного слова раскрывается через контекст, а письмо строится на конкретных фактах и личном отношении автора.`,
    },
    122: {
      question: `Выполните орфографический и пунктуационный практикум: восстановите текст о территории и природных ресурсах России.`,
      answer: `К числу важнейших ресурсов нашей страны относится и её территория. Вам известно, что площадь Российской Федерации — 17 125 191 км². Канада, находящаяся на втором месте, и Китай, занимающий третью позицию, имеют площадь почти в два раза меньше России. Можно сравнить размеры России и не совсем обычно. Запоминайте: наша территория равна почти половине (46 %) Луны; более чем двум континентам, равным Австралии; восьми Гренландиям; 37 807 727 таким государствам, как Ватикан — самое маленькое государство в мире.\nПриродные ресурсы, которыми издавна славится наша страна, обеспечивают развитие нашей страны. Если бы на Земле было всего одно пресноводное озеро — наш Байкал, — то, при условии, что каждый житель планеты ежедневно потребляет 500 литров пресной воды, люди всей Земли могли бы прожить на одной только байкальской воде не менее 40 лет.`,
      rule: `Причастные обороты после определяемого слова обособляются; «не совсем» и «издавна» пишутся раздельно и слитно соответственно; названия планет и государств — с прописной буквы.`,
    },
    123: {
      question: `Назовите и объясните основные признаки текста по справочной схеме.`,
      answer: `Основные признаки текста: смысловая цельность, информативность и связность. Смысловая цельность означает наличие общей темы, основной мысли и завершённого замысла. Информативность — способность передавать фактуальную, подтекстовую и концептуальную информацию. Связность — логическое и языковое соединение предложений и абзацев при помощи повторов, местоимений, союзов, последовательности времён и других средств. Текст также имеет композицию: начало, развитие мысли и завершение.`,
      rule: `Набор предложений становится текстом, если они объединены темой и замыслом, несут информацию и связаны по смыслу и грамматически.`,
    },
    124: {
      question: `Восстановите последовательность предложений в истории о бабочке А. И. Куинджи, назовите средства связи, синонимические наименования художника и объясните оценку Н. К. Рериха.`,
      answer: `Правильная последовательность: 2 → 3 → 1 → 5 → 4. Сначала бабочка случайно залетела в мастерскую и примёрзла к стеклу; затем, пытаясь освободиться, повредила крыло; Куинджи принялся её спасать; сделал каркас и бумажные заплатки; после этого бабочка снова полетела. Связь создают повтор «бабочка», местоимения «она», «он», слова времени и следствия «пробуя», «и вот», «вновь», а также причинно-следственная логика.\nСинонимы и контекстные наименования Куинджи: знаменитый художник, живописец, мастер, он. Известные картины: «Лунная ночь на Днепре», «Берёзовая роща», «Эльбрус. Лунная ночь». Н. К. Рерих называет Куинджи великим Учителем жизни, потому что он воспитывал учеников не только искусством, но и добротой, состраданием, вниманием к живому.`,
      rule: `Последовательность восстанавливают по хронологии действий, местоименным заменам, повторам и причинно-следственным связям.`,
    },
    125: {
      question: `Докажите, что фрагмент книги В. П. Катаева «Трава забвенья» является текстом, объясните мысль последнего абзаца и роль коротких однофразовых абзацев.`,
      answer: `Это текст: все предложения объединены темой творческого восприятия мира, последовательно развивают одну мысль, связаны повтором местоимения «я», словами «например», «во всяком случае», «сейчас же» и завершаются обобщением. Автор говорит о способности мысленно становиться людьми, животными, растениями, предметами и даже отвлечёнными понятиями.\nПоследний абзац означает: писатель непрерывно впитывает окружающий мир; увиденное становится частью его личности и будущего творчества, а он сам оставляет частицу себя в каждом образе. Второй и третий абзацы состоят из одного предложения, чтобы замедлить чтение, выделить пример «квадратного корня» и отдельно подчеркнуть, что такая способность свойственна каждому человеку.`,
      rule: `Абзацное членение передаёт ход мысли: короткий абзац может выделять пример, поворот или важный тезис.`,
    },
    126: {
      question: `Проанализируйте фрагмент статьи А. Н. Толстого «Родина»: найдите тематические и концептуальные предложения, противопоставления, объясните выражение «земля отцов и дедичей» и роль сравнений.`,
      answer: `Тематические предложения вводят этапы мысли: в мирные годы человек может далеко отлететь от родного «гнезда»; при общей беде все собираются у него; Родина тогда овладевает чувствами людей. Концептуальное предложение — финальное: живущие в лихолетье люди становятся «хранителями и сторожами родины нашей».\nПротивопоставлены мирные годы и война, счастливый и несчастный человек, возможность жить отдельно и необходимость сплотиться, прежняя привычность родного и его внезапно осознанная ценность. «Земля отцов и дедичей» — не просто территория, а унаследованная от предков Родина, за которую современное поколение отвечает. Сравнения «человек, как птица», Родина как гнездо, желание спрятаться «как сверчок» делают мысль наглядной: в опасности люди возвращаются к общему дому и ощущают единство.`,
      rule: `Тематическое предложение называет предмет абзаца, а концептуальное выражает авторскую оценку и главную идею всего текста.`,
    },
    127: {
      question: `Дополните таблицу о дедуктивной, индуктивной, рамочной и стержневой структурах текста.`,
      answer: `Дедуктивная структура: сначала формулируется обобщение, затем оно объясняется, доказывается и конкретизируется частными примерами. Схема: СБО → детали.\nИндуктивная структура: изложение идёт от частных фактов и наблюдений к общему выводу. Схема: детали → СБО.\nРамочная структура: в начале дано обобщение, далее — конкретизация, а в конце мысль снова обобщается и уточняется. Схема: СБО → детали → СБО.\nСтержневая структура: сначала приводятся подробности, затем обобщение, после которого следуют новые частные пояснения. Схема: детали → СБО → детали.\nСБО — смысловой блок обобщения.`,
      rule: `Вид структуры определяется местом главного обобщения относительно частных фактов и примеров.`,
    },
    128: {
      question: `Определите тематические предложения и вид структуры трёх фрагментов о весне, болотах и диатомовых водорослях.`,
      answer: `Пример Б. Пастернака имеет дедуктивную структуру: тематическое начало «Ночь принесла много неожиданного», затем перечисляются подтверждающие детали — тепло, дождь, исчезновение снега, почернение земли.\n1. Текст о болотах — индуктивный: сначала приведены факты о поглощении углекислого газа и выделении кислорода, затем вывод: болота действуют как природные «ловушки» углекислого газа и поддерживают устойчивость атмосферы.\n2. Текст о торфе — дедуктивный: тезис «Болота выполняют функцию природного пылесоса» объясняется движением пыли и числами, показывающими объём её накопления.\n3. Текст о диатомовых водорослях — рамочный: начальное обобщение об их распространении по всему земному шару конкретизируется перечислением мест обитания и завершается итогом о вездесущности и разных требованиях видов.`,
      rule: `Речевые подсказки «то есть», «объясняется это тем», «например» показывают вывод, объяснение и пример.`,
    },
    129: {
      question: `Выполните орфографический практикум: восстановите фрагмент В. Розанова о лучшем в прошлом.`,
      answer: `Что самое лучшее в прошедшем и давно прошедшем? Свой хороший или мало-мальски порядочный поступок.\nИ ещё — добрая встреча: то есть узнание доброго, подходящего, милого человека. Вот это в старости ложится светлой, светлой полосой, и с таким утешением смотришь на эти полосы, увы, немногие.\nНо шумные удовольствия (у меня немного)? Так называемые «наслаждения»? Они были приятны только в момент получения и не имеют никакого значения для «потом».\nТолько в старости узнаёшь, что «надо было хорошо жить». В юности это даже не приходит на ум. И в зрелом возрасте — не приходит. А в старости воспоминание о добром поступке, о ласковом отношении, о деликатном отношении — единственный «светлый гость» в «комнату» (в душу).`,
      rule: `Сложные прилагательные типа «мало-мальски» пишутся через дефис; цитатные и условные наименования берутся в кавычки; перечисление разделяется запятыми.`,
    },
    130: {
      question: `Сопоставьте варианты названий пяти книг, определите их характер, адресата, роль заголовка и синтаксическую структуру.`,
      answer: `Нейтральные научно-учебные заголовки прямо называют тему: «Русская пунктуация», «Фонетика», «Культура речи», «Обучение чтению», «Лингвистическая энциклопедия». Более привлекательны для школьников образные, вопросительные и обещающие открытие варианты: «Секреты пунктуации», «От точки до точки...», «Фонетика — это интересно», «Как говорить правильно и как говорить хорошо?», «Открываем секреты Цицерона», «Учитесь читать быстро и эффективно», «Читаем правильно...», «Энциклопедия юного филолога». Они вызывают любопытство и подчёркивают практическую пользу.\nЗаголовок называет тему, задаёт ожидания, привлекает внимание и помогает выбрать книгу. По строению есть назывные словосочетания («Культура речи»), повествовательные предложения («Фонетика — это интересно»), вопросы, побудительные предложения и конструкции с перечислением.`,
      rule: `Тип и синтаксис заголовка зависят от адресата и цели: сообщить тему, заинтересовать, задать вопрос или побудить к действию.`,
    },
    131: {
      question: `Подготовьте сообщение об особенностях и видах заголовков СМИ по схеме.`,
      answer: `Заголовок СМИ выполняет четыре основные задачи: сообщает тему, привлекает внимание, формирует отношение к материалу и приглашает читателя к диалогу. Фактический заголовок прямо передаёт главную новость или факт и обычно нейтрален: «В городе открылась новая школа». Образный заголовок вызывает эмоцию, передаёт идею и часто строится на метафоре или игре слов: «Школа открывает двери в будущее». Заголовок-клише использует известную цитату, пословицу или устойчивое выражение: «Ученье — свет», а подзаголовок уточняет тему. Удачный заголовок точен, связан с текстом, понятен адресату и не обещает того, чего в публикации нет.`,
      rule: `Фактический, образный и клишированный заголовки различаются способом представления темы, но каждый должен соответствовать содержанию.`,
    },
    132: {
      question: `Распределите десять заголовков на фактические, образные и заголовки-клише; предложите примеры и оцените, какие заголовки понятнее без текста.`,
      answer: `Фактические: 1) «Банкам не хватает денег»; 3) «К марту будут закончены работы по возведению моста»; 5) «Нефть подешевела на доллар»; 10) «Стратегия и тактика успеха».\nОбразные: 2) «ВыГений нашего времени»; 7) «Делу не хватает жизни»; 8) «Изменился аппетит инвесторов»; 9) «НеслуЧАЙная встреча».\nЗаголовки-клише: 4) «Семь раз отмерь — один отрежь»; 6) «Кадры решают всё».\nСвои примеры: фактический — «В школе открылся медиакласс»; образный — «Урок длиною в будущее»; клише — «Век живи — век учись: как меняется образование». Точнее всего без текста прогнозируются фактические заголовки. Образные и клишированные лучше привлекают внимание, но часто нуждаются в подзаголовке, иначе содержание угадывается лишь приблизительно.`,
      rule: `Факт сообщает событие прямо, образ переносит значение, а клише преобразует узнаваемую формулу.`,
    },
    133: {
      question: `Сравните произведения с одинаковыми названиями: две сказки «Самовар», другие литературные совпадения и сказку Х. К. Андерсена с пьесой Е. Л. Шварца «Тень».`,
      answer: `В сказке М. Горького самовар — главный одушевлённый персонаж: пузатый самовар влюблён в чайник, поэтому название обозначает героя. У Л. Петрушевской самовар — забытый предмет, вокруг которого разворачивается судьба вещи; название указывает на тему и центр сюжета.\nПримеры одинаковых названий: «Кавказский пленник» А. Пушкина, М. Лермонтова и Л. Толстого; «Метель» А. Пушкина и Л. Толстого; «Два брата» у разных сказочников. Совпадение названия не означает совпадения сюжета или идеи.\nУ Андерсена главным противником учёного становится его собственная Тень: она приобретает власть и губит хозяина; финал трагичен. Шварц переосмысливает мотив в пьесе о борьбе учёного с общественным злом; его герой в итоге заставляет Тень знать своё место. Эпиграф подчёркивает связь с Андерсеном, а название обозначает одновременно персонажа и нравственную идею — тёмную сторону человека и общества.`,
      rule: `Заголовок может называть героя, предмет, тему или идею; одинаковое слово получает новый смысл в контексте каждого произведения.`,
    },
    134: {
      question: `Сравните начала «Кавказского пленника» А. С. Пушкина, М. Ю. Лермонтова и Л. Н. Толстого и определите, раскрывается ли тема в каждом заголовке одинаково.`,
      answer: `У Пушкина и Лермонтова произведения начинаются романтической картиной аула и черкесов; стихотворная форма, пейзаж и экзотическая обстановка создают возвышенное ожидание истории пленника. Начала близки даже лексически: «В ауле... черкесы... сидят».\nТолстой начинает с предельно простой фактической фразы: «Служил на Кавказе офицером один барин. Звали его Жилин». Сразу назван конкретный герой, а повествование обещает реалистический рассказ о его поступках. Во всех трёх текстах название указывает на плен русского человека на Кавказе, но темы раскрываются по-разному: романтическое столкновение миров у поэтов и нравственное испытание деятельного героя у Толстого.`,
      rule: `Одно название может объединять произведения общим мотивом, а жанр, стиль и авторская идея меняют способ его раскрытия.`,
    },
    135: {
      question: `Проанализируйте рекламные шаблоны заголовков, оцените их убедительность и создайте свои варианты.`,
      answer: `Шаблоны строятся на вопросе о желании читателя, обещании секрета от известного человека, обращении к тем, кто не может сделать первый шаг, интригующем контрасте «они смеялись..., но когда...», заявлении о найденной тайне. Они привлекают любопытством, но без конкретики превращаются в кликбейт. Наиболее удачны вопросительный и контрастный шаблоны, если публикация действительно даёт обещанную пользу.\nЗаполнение: «Вы бы хотели запоминать иностранные слова вдвое быстрее?»; «Опытный реставратор раскрывает безопасные способы ухода за старинными книгами»; «Для тех, кто хочет вести школьную газету, но не знает, с чего начать»; «Они смеялись, когда я записался в театральный кружок, но замолчали, когда начался спектакль»; «Найдены, пожалуй, самые необычные способы экономить воду дома».\nСвой шаблон: «Пять проверенных шагов, которые помогут вам ... без ...». Пример: «Пять проверенных шагов, которые помогут подготовить доклад без ночной зубрёжки».`,
      rule: `Удачный привлекающий заголовок конкретен, правдив и соответствует материалу; интрига не должна подменять содержание.`,
    },
    136: {
      question: `Объясните использование строк А. С. Пушкина в современных заголовках и придумайте несколько заголовков для школьной газеты с литературными аллюзиями.`,
      answer: `Пушкинская строка узнаваема и создаёт игру между исходным текстом и новой темой: «Что год пришедший нам готовит?» переносит ожидание будущего на новый год; «Что старт грядущий нам готовит?» — на соревнование; «Что веб грядущий нам готовит?» — на развитие Интернета.\nВарианты для школьной газеты: «И опыт, сын ошибок трудных» — о школьной научной конференции; «Унылая пора! Очей очарованье!» — о конкурсе осенней фотографии; «В одну телегу впрячь не можно...» — о трудностях командного проекта; «На берегу пустынных волн...» — об экологической акции у реки; «Мороз и солнце — день спортивный!» — о зимних соревнованиях.`,
      rule: `Аллюзия работает, если читатель узнаёт источник и понимает связь преобразованной цитаты с новой темой.`,
    },
    137: {
      question: `Выполните орфографический и пунктуационный практикум: восстановите текст о точке после заголовка и обращения в письме.`,
      answer: `Чтобы не было мучительно неловко, не ставьте точку после заголовка\n\nДействительно, точка после заголовка — это лишний знак. В современной русской письменной печати ставить её не принято. Но в обычных учебниках русского языка такого правила не найти. Это положение узаконено специальными пособиями и справочниками для корректоров и редакторов. Вот что сказано в «Справочной книге редактора и корректора» под редакцией А. Э. Мильчина (1985): «Точку в рубрике, вынесенной в отдельную строку, опускают, за исключением изданий для начинающих читать детей (например, в букваре), чтобы не мешать закреплению стереотипа: в конце предложения надо ставить точку».\nА ещё точку не стоит ставить после обращения в официальном письме. У обращения — особая, звательная интонация. А точка её убивает, гасит. Нет, такая конструкция довольно странна: «Уважаемая Мария. Я получил Ваше письмо...» Кстати, многие российские и зарубежные лингвисты отмечают: в последнее время точка в переписке — как деловой, так и бытовой — стала знаком обиды, угрюмости и даже агрессии. Лучше поставить восклицательный знак («Уважаемая Мария!») или запятую («Уважаемая Мария, ...»).`,
      rule: `Точка в конце отдельного заголовка не ставится; обращение в письме оформляют восклицательным знаком либо запятой с продолжением фразы.`,
    },
    138: {
      question: `Проанализируйте басню С. В. Михалкова «Аисты и лягушки»: предмет и исход спора, похожие сюжеты и признаки разговорной речи.`,
      answer: `Аист и Лягушка спорят, у кого красивее ноги. Каждый сравнивает только выгодные себе признаки: Аист гордится длинными ногами, Лягушка — четырьмя ногами, умением квакать, летать или нырять. Спор не разрешается, потому что стороны не договариваются об общем критерии и лишь отвечают новой похвальбой. Рассказчик заключает, что не зря говорят: аисты глотают лягушек, чтобы не спорить с ними.\nПохожий спор о красоте лежит в древнегреческом мифе о суде Париса, где Гера, Афина и Афродита претендуют на звание прекраснейшей. В басне слышна разговорная речь: короткие реплики, повторы «а у меня», частицы «да», «зато», «подумаешь», неполные предложения, простая лексика и эмоциональная интонация.`,
      rule: `Спор нельзя решить без общего основания сравнения; диалог передаёт разговорность короткими репликами, повторами и частицами.`,
    },
    139: {
      question: `Объясните происхождение слов «спор» и «прения», составьте с родственными словами сочетания и предложения, постройте словообразовательное гнездо.`,
      answer: `«Спор» и «прения» восходят к древним корням со значением борьбы и состязания. «Спор» образован от старославянского «прети» с приставкой с-, а «прения» — с суффиксом -ени-. «Соперник» исторически содержит тот же корень и буквально обозначает противника. Поэтому переносное значение спора как соперничества закономерно.\nСочетания: научный спор, вступить в спор, спорить о языке, спорный вывод, бесспорное доказательство, оспаривать решение, переспорить собеседника, судебные прения, политические прения. В научном стиле: «Учёные оспаривают прежнюю гипотезу». В официальном: «Стороны перешли к судебным прениям». В разговорном: «Мы поспорили о фильме».\nГнездо: спор → спорить → поспорить, заспорить, переспорить, проспорить; спор → спорный → бесспорный, неспорный; спор → спорщик, спорщица; оспорить → оспаривать, оспаривание. Для проверки используется словообразовательный словарь.`,
      rule: `Этимологическое родство объясняет историю корня, а словообразовательное гнездо показывает современные производные одного исходного слова.`,
    },
    140: {
      question: `Объясните метафорические значения слова «спор» в стихотворных строках и приведите собственные примеры, где спорят не только люди.`,
      answer: `У Н. Рубцова «вечный спор» ведут ветер и хвоя — это их шумное столкновение; «спор гармошек» — перекликающиеся и соперничающие мелодии. У Г. Иванова «спор с бесчеловечною судьбой» означает сопротивление судьбе. У Д. Самойлова «спор со временем» — противостояние человека ходу эпохи и забвению.\nИтак, спорить могут не только люди, но и силы природы, звуки, идеи, чувства и человек с отвлечённым понятием. Примеры: «Всю ночь ветер спорил с морем»; «Солнечный луч спорил с последним снегом»; «В его душе надежда спорила со страхом»; «Старинный дом спорит с новыми высотками». Во всех случаях глагол обозначает образное столкновение противоположных сил или признаков.`,
      rule: `Метафора переносит действие людей на природу, звуки и отвлечённые понятия по сходству борьбы или противодействия.`,
    }
  });

  Object.assign(solutions, {
    141: {
      question: `Оцените речевое поведение участников двух школьных споров и допишите реплики так, чтобы спор не перерос в конфликт.`,
      answer: `Ситуация 1. Учитель преждевременно объявляет ученика неготовым и затем публично высмеивает его ответ. Максим защищается, но обвинительная реплика «Вы просто не даёте мне ответить!» усиливает конфликт. Лучше сказать: «Разрешите, пожалуйста, я отвечу до конца и покажу, что подготовился». Реплика учителя после ответа: «Максим, я поспешил с выводом. Ты знаешь материал, но в одном месте ошибся; давай спокойно разберём это место».\nСитуация 2. Учитель прав, исправляя «ложить» на «класть», но не должен насмешливо оценивать отца ученика. Продолжение: «Люди могут ошибаться независимо от ума и образования. В литературной речи без приставки употребляют “класть”, а с приставкой — “положить”. Постарайся запомнить и объясни правило дома без упрёка». Ответ ученика: «Спасибо, теперь понятно. Я буду говорить правильно».`,
      rule: `Спор не становится конфликтом, если обсуждают ошибку, а не личность, дают договорить и используют спокойные просьбы вместо обвинений.`,
    },
    142: {
      question: `Проанализируйте фрагмент М. М. Жванецкого «Стиль спора»: что высмеивает сатирик, зачем использованы вопросы и какие правила достойного спора следуют из «вредных советов».`,
      answer: `Сатирик высмеивает спор без фактов, переход на личность, давление темпераментом, проверку статуса вместо аргументов, насмешки над внешностью, перебивание и грубое «тыканье». Вопросы «О чём может спорить человек, который не поменял паспорт?» и «Какие взгляды... может высказать мужчина без прописки?» намеренно нелепы: они показывают, что документы и внешность никак не определяют правильность мысли. Это риторические вопросы, усиливающие сатиру.\nПравила достойного спора: 1) обсуждать предмет, а не личность; 2) приводить проверяемые факты; 3) внимательно слушать; 4) не перебивать и не унижать; 5) сохранять уважительное обращение; 6) задавать уточняющие вопросы; 7) признавать сильный аргумент и свою ошибку; 8) искать истину или решение, а не победу любой ценой.`,
      rule: `Переход на личность не опровергает довод; корректный спор строится на аргументах, логике и уважении к партнёру.`,
    },
    143: {
      question: `Подготовьте краткое сообщение о взглядах славянофилов и западников XIX века на развитие русского языка.`,
      answer: `Славянофилы отстаивали самобытный путь России. В языке они ценили народную речь, древнерусскую и церковнославянскую традицию, считали важным сохранять национальный строй языка и осторожно относились к избытку иностранных слов.\nЗападники связывали развитие России с европейским опытом. Они принимали обновление словаря, международные термины и новые жанры, выступали за современный, ясный литературный язык, способный передавать идеи науки, общественной жизни и культуры.\nОбе стороны влияли на развитие нормы: спор помог осмыслить равновесие между национальной традицией и необходимыми заимствованиями. Русский язык развивался не через полную изоляцию и не через механическое копирование, а через отбор и освоение новых средств.`,
      rule: `Исторический языковой спор нужно показывать с обеих сторон, различая сохранение национальной традиции и открытость культурному обмену.`,
    },
    144: {
      question: `Выполните орфографический и пунктуационный практикум: восстановите текст об истине, правде и споре в русской культуре.`,
      answer: `Говорят, что в споре рождается истина. Насколько это справедливо для понимания спора в русской культуре?\nВ толковых словарях русского языка выделяются две идеи в определении понятия «истина»: 1) истина — то, что соответствует действительности; 2) истина — то, что существует в действительности. В современном русском сознании слово «истина» образует прочную пару со словом «правда». Характерным для русской лингвокультуры является понимание правды как справедливости. Для достижения истины в спорах среди носителей русской культуры считается воссоздание достоверности, принятие правильных решений или восстановление справедливости.`,
      rule: `Слова «рождается», «понимание», «определение», «действительность», «воссоздание» и «восстановление» пишутся по морфемному составу; определения после цифр оформляются тире.`,
    },
    145: {
      question: `По школьной новости о поездке по Ярославскому краю дайте определение жанра «путевые заметки».`,
      answer: `Путевые заметки — литературно-публицистический жанр, в котором автор по ходу путешествия кратко записывает маршрут, события, сведения о местах и людях, собственные наблюдения, впечатления и размышления. В тексте о поездке названы Углич и Мышкин, местные достопримечательности и виды деятельности школьников; факты соединены с оценкой «увлекательное», «приятное», «интересные сведения и впечатления».`,
      rule: `Жанр определяют по цели, содержанию и форме: путь задаёт последовательность, факты сообщают сведения, а авторские впечатления придают тексту личный характер.`,
    },
    146: {
      question: `Проанализируйте путевые записи школьников: соотношение объективного и субъективного, особенности жанра и возможные фотографии-иллюстрации.`,
      answer: `В заметках есть объективные сведения: время выезда и прибытия, маршрут Москва — Мартыново — Мышкин — Углич, названия музеев, гостиницы и блюд. Однако преобладает субъективное восприятие: восклицания «Путешествие началось!», «А вот и Мышкин!», оценки «интереснейший», «настоящая кузница», упоминания впечатлений, страха и веселья. Особенность жанра — соединение хронологической записи пути с фактами, описаниями, эмоциями и личными наблюдениями.\nФотография Музея гидроэнергетики иллюстрирует посещение угличского музея, а снимок Музея валенок — рассказ о фигурках мышей, тапочках, сапогах и валенках. Полезны также карта маршрута, виды Волги, Угличского кремля, Мышкина, кузницы и школьников на экскурсии.`,
      rule: `Путевая заметка сочетает документальность маршрута с личной оценкой автора; иллюстрация должна подтверждать конкретный фрагмент записи.`,
    },
    147: {
      question: `Объясните значение диалектов для истории языка, приведите примеры местных слов и покажите, почему сохранение языка зависит от изученности говоров.`,
      answer: `Диалекты сохраняют старые слова, значения, произношение и названия местных реалий, поэтому по ним восстанавливают историю народа, быт и отношение к природе. Примеры из текста: «векша» — белка; «бирюк, бирючина» — большой медведь; «бачажинник, бачажник» — густые заросли кустарника; «сеновной» — мелкий продолжительный дождь во время сенокоса; «огуречник» — тёплый грибной дождь в конце июня. В своём регионе к ответу можно добавить названия местной еды, предметов быта, погоды и природных явлений.\nИзучение говоров сохраняет национальный язык, потому что фиксирует исчезающие слова и точные народные различия. Например, литературному языку достаточно слова «дождь», а диалекты называют его по продолжительности, температуре и влиянию на хозяйство. Потеря таких слов означает потерю части исторического опыта.`,
      rule: `Диалектизм — территориально ограниченное слово или форма; в исследовании обязательно записывают значение и место употребления.`,
    },
    148: {
      question: `Проанализируйте фрагмент книги Я. К. Голованова «Дорога на космодром»: признаки публицистического стиля, заголовок, выразительные средства и краткий пересказ.`,
      answer: `Публицистический стиль проявляется в общественно значимой теме космонавтики, документальных деталях, авторском «я», оценочной лексике, эмоциональных фразах и риторическом вопросе. Информация соединена с художественным описанием дороги и личным отношением к космонавтам. Заголовок: «Обыкновенная дорога к звёздам».\n«Колючие шары перекати-поля — так море прибивает к пирсу ненужные ему щепки» — развёрнутое сравнение; «силуэты, похожие на вазочки для мороженого» — сравнение; «тоненькая ажурная вышка» — оценочные эпитеты; «сколько лет прошло, а каждый раз ждёшь этого мига» — противопоставление и эмоциональное усиление.\nПересказ: автор едет по степному шоссе к космодрому. Вдали появляются радиотелескопы и стартовая вышка. Сегодня улетает знакомый экипаж; для космонавтов это работа, но автор снова волнуется. Он вспоминает мысль Сенеки о вечном стремлении человека к звёздам и связывает её с полётом Гагарина.`,
      rule: `Публицистика убеждает и волнует, соединяя общественно важные факты с оценкой, образами и авторской позицией.`,
    },
    149: {
      question: `Выполните орфографический и пунктуационный практикум: восстановите текст Я. Голованова о стремлении человека в космос.`,
      answer: `Человек поднялся в космос прежде всего потому, что он Человек, что такой полёт, враждебный его телу, желанен его душе, что полёт этот подготовлен всей историей Человека, всеми предыдущими его победами над силами природы. Человек не мог не открыть Америки — и в море ушли каравеллы Христофора Колумба; не мог не убедиться, что Земля — шар, — и невиданным своим упорством пробил дорогу в Великий океан Фернандо Магеллан. Человек не мог не научиться летать выше облаков и опускаться в океанские пучины. Мифы не знают пределов фантазии: в мифах можно было придумать самую фантастическую, самую умную машину и научить её летать подобно птице, но в мифах летал Икар — Человек. «Восток» мог вместить множество приборов и датчиков, но в кресле «Востока» сидел Гагарин — Человек.`,
      rule: `Конструкции «не мог не» пишутся с двумя раздельными «не»; уточняющие определения обособляются, пояснение оформляется тире или двоеточием.`,
    },
    150: {
      question: `Проанализируйте три социальных плаката о чтении: связь изображения и текста, выразительность заголовков и знаки препинания.`,
      answer: `1. «Книги делают человека выше»: переносный смысл духовного роста буквально показан людьми, стоящими на стопках книг. 2. «Стремись к вершине! Читай!»: книги изображены горой, поэтому метафора вершины соединяет чтение с достижением цели. 3. «Расширяй горизонты!»: лестница из книг и электронное устройство ведут к облакам и зрительно передают расширение знаний. Без рисунка тексты понятны, но более общи; без текста рисунки допускают разные толкования. Вместе они дают точный рекламный призыв.\nБольше всего убедителен второй плакат: короткий ритмичный лозунг и ясный образ вершины. Заголовки рекламны: кратки, образны, обращены к читателю и используют повелительное наклонение. Восклицательные знаки передают призыв и энергию; в первом плакате точка не нужна, поскольку это отдельный слоган-заголовок.`,
      rule: `В плакате вербальная и зрительная информация дополняют друг друга, а краткий слоган выражает главную мысль и побуждение.`,
    },
    151: {
      question: `Объясните понятие социальной рекламы, составьте план текста, сравните её с коммерческой и предложите собственный вариант.`,
      answer: `Социальная реклама — информация, направленная на общественные и государственные интересы и достижение благотворительных целей. Её объект — общественная проблема, ценность или полезная модель поведения: безопасность, здоровье, помощь людям, защита природы, культура.\nПлан текста: 1) зачем нужна социальная реклама; 2) происхождение и близкие названия термина; 3) определение в законе; 4) заказчики и формы; 5) отличие от коммерческой рекламы; 6) необходимость сильной эмоции. Дополнить можно примерами кампаний по безопасности на дорогах, донорству, бережному отношению к воде и против травли.\nСоциальный текст часто труднее коммерческого: нужно изменить привычку, не обещая покупателю личной выгоды, затронуть сильные чувства и при этом не запугать и не унизить человека. Вариант плаката: изображение капли, превращающейся в реку; слоган «Закрой кран сегодня — сохрани реку завтра». Подпись: «Проверь воду перед выходом из дома».`,
      rule: `Коммерческая реклама продвигает товар или услугу, социальная — общественно полезную ценность и изменение поведения.`,
    },
    152: {
      question: `Проанализируйте два-три рекламных текста по их языковым приёмам и подготовьте короткое сообщение.`,
      answer: `Для анализа подходят плакаты из упражнения 150. «Книги делают человека выше» использует многозначность: «выше» означает и физическое положение на стопке, и духовный рост. «Стремись к вершине! Читай!» строится на метафоре: вершина — высокий результат, а книги — путь к нему; повелительные предложения прямо побуждают к действию. «Расширяй горизонты!» — метафора увеличения кругозора; изображение лестницы из книг делает переносный смысл наглядным.\nКороткое сообщение: рекламный язык стремится выразить максимум смысла минимумом слов. Поэтому авторы используют многозначность, метафору, аллюзию, повтор, ритм и побудительные предложения. Рисунок раскрывает игру слов, а слоган направляет толкование изображения. Приём удачен только тогда, когда он понятен и связан с рекламируемой идеей.`,
      rule: `Рекламный приём одновременно привлекает внимание, облегчает запоминание и связывает образ с требуемым действием.`,
    },
    153: {
      question: `Проанализируйте текст об англицизмах и пиджинизации: определите опасность, функции пиджинов, возможность словарей и выразите своё мнение.`,
      answer: `Автор предупреждает: массовое некритичное копирование английских моделей в рекламе может вытеснять привычные русские способы словообразования и культурные ориентиры. Крайний результат такого упрощения назван пиджинизацией. Пиджин — контактный язык с небольшим словарём, упрощённой грамматикой и ограниченными функциями, возникающий у людей без другого общего средства общения; обычно у него нет носителей как родного языка.\nПиджины обеспечивают практический контакт в торговле, труде и быту. Их словари возможны и существуют, потому что даже небольшой и изменчивый набор слов можно собирать, описывать и сопоставлять; пример — русско-норвежский, русско-китайский, таймырский пиджины и язык алеутов острова Медный.\nС опасением можно согласиться частично. Заимствование само по себе естественно и полезно, если называет новое явление. Опасность возникает, когда английское слово без необходимости заменяет понятное русское, делает сообщение неясным или служит только моде. Нужны точность, уместность и языковая мера, а не полный запрет.`,
      rule: `Заимствование оценивают по необходимости, понятности и способности освоиться в системе языка; контактный пиджин не равен обычному пополнению словаря.`,
    },
    154: {
      question: `Выполните орфографический и пунктуационный практикум: восстановите текст А. Гениса о русских суффиксах.`,
      answer: `Попробуйте обойтись без суффиксов — и ваша речь уподобится голосу автомобильного навигатора, который не умеет, как, впрочем, и многие другие, склонять числительные и походить на человека. Приделав к слову необязательный кончик, мы дирижируем отношениями с тем же успехом, с каким японцы распределяют поклоны, тайцы — улыбки, французы — поцелуи и американцы — зарплату. Суффиксы утраивают русский словарь, придавая каждому слову синоним и антоним, причём сразу. Хорошо или плохо быть «зубиком», как я понял ещё пионером, зависит от того, кто тебя так зовёт — учительница или подружка. Дело в том, что в русском языке, как и в русской жизни, нет ничего нейтрального. Каждая грамматическая категория, даже такая природная, как род, — себе на уме.`,
      rule: `Вводные и сравнительные обороты обособляются; неполные параллельные конструкции разделяются запятыми и тире; деепричастный оборот выделяется запятой.`,
    },
    155: {
      question: `Сопоставьте научный текст о фазах Луны и стихотворение С. Я. Маршака: явление, содержание, художественные признаки, задачи авторов и образы Луны в поэзии.`,
      answer: `Оба текста говорят о смене лунных фаз: после новолуния появляется серп, он увеличивается, проходит первую четверть и становится полным диском. В научном тексте процесс объяснён положением Луны относительно Земли и Солнца. В стихотворении полумесяц идёт к портному за платьем, но за четырнадцать дней вырастает в полный месяц.\nНаучный фрагмент сообщает точные сведения и употребляет термины: фаза, новолуние, лунный серп, пепельный свет, первая четверть, полнолуние. Стихотворение создаёт художественный образ при помощи олицетворения, диалога, рифмы, юмора и сюжета. Иллюстрации: к первому тексту — схема фаз Луны; ко второму — полумесяц на примерке у портного.\nВ русской поэзии употребительны оба образа. «Луна» чаще нейтрально называет небесное светило и полный диск, «месяц» особенно характерен для народно-поэтической речи и образа серпа. К теме обращались А. Пушкин, М. Лермонтов, Ф. Тютчев, А. Блок, С. Есенин, А. Ахматова.`,
      rule: `Научный текст объясняет явление терминами и причинными связями, художественный создаёт образ и эмоциональное впечатление.`,
    },
    156: {
      question: `Распределите вопросы к тексту по видам информации и объясните, в каких стилях встречается только фактуальная, а в каких нужны все три вида.`,
      answer: `Фактуальную информацию выявляют вопросы: кто действует, что делает, кто или что описывается, где и когда происходит событие, каким образом оно происходит. Подтекстовую помогают понять вопросы: почему герой так поступил, что он хотел сказать фразой, почему одно событие следует за другим, зачем употреблено слово, почему абзац короток или фраза заканчивается восклицательным знаком. Концептуальную раскрывают вопросы: какова проблема, как относится к ней автор, какова главная идея и оценка.\nПочти только фактуальная информация нужна в официально-деловых документах, инструкциях, расписаниях и кратких справочных статьях: их цель — однозначно сообщить данные, а не создавать подтекст. Все три вида особенно важны в художественных и публицистических жанрах: читатель узнаёт события, восстанавливает не названные прямо смыслы и понимает авторскую идею.`,
      rule: `Факт отвечает «что произошло», подтекст — «что подразумевается», концепция — «ради какой общей мысли создан текст».`,
    },
    157: {
      question: `Сформулируйте нравственный урок притчи «Все мои леса, все мои луга!» и оцените предложенное толкование.`,
      answer: `Нравственный урок: успех и благополучие не дают человеку права считать мир своей собственностью и приписывать все достижения только себе. Самоуверенность быстро исчезает перед трудностью, поэтому нужно сохранять скромность, благодарность и помнить о зависимости от людей и природы.\nПредложенное толкование справедливо: в счастье человек иногда преувеличивает свою власть, а несчастье обнаруживает её границы. Образ жука — иносказание: в солнечный день он хвастается «своими» лесами и лугами, но при ветре цепляется за листок и просит не столкнуть. Однако испытание должно вести не к унижению, а к трезвой оценке себя и ответственности.`,
      rule: `Мораль притчи выводится из аллегорического сюжета: поведение условного персонажа переносится на человеческую жизнь.`,
    },
    158: {
      question: `Выберите из перечня признаки жанра притчи и объясните выбор.`,
      answer: `Подходят признаки: 1) малый объём; 2) иносказание; 3) сюжетная линия чаще сосредоточена вокруг одного персонажа; 5) сюжет из обыденной жизни. Притча кратко показывает типичную ситуацию и предлагает через неё увидеть нравственный смысл.\nНеобязательны: 4) широкое изображение жизни и множество подробно раскрытых героев — это признак крупных эпических жанров; 6) реальный случай в основе — сюжет может быть вымышленным; 7) сказовая форма — притча не обязана имитировать устный рассказ.`,
      rule: `Главные свойства притчи — краткость, иносказательный пример, нравственная проблема и возможность самостоятельно вывести урок.`,
    },
    159: {
      question: `Проанализируйте притчу Л. Н. Толстого «Ровное наследство»: жанровые признаки, нравственный урок и вид информации, из которой он выводится.`,
      answer: `Жанровые признаки: небольшой объём, простой сюжет из семейной жизни, немного персонажей без подробных портретов, противопоставление двух братьев и скрытый нравственный вывод. Отец хочет отдать наследство старшему; узнав об этом, младший уезжает, учится мастерствам и наукам. Старший, уверенный в будущем богатстве, ничему не учится. После смерти отца он теряет имение, а младший благодаря знаниям становится состоятельным.\nУрок: знания, труд и умение самостоятельно зарабатывать надёжнее наследства; гарантированное богатство без труда развращает, а необходимость действовать развивает человека. Это концептуальная информация. Она не сформулирована автором прямо, а выводится из фактуальной последовательности событий и противопоставления судеб братьев.`,
      rule: `В притче мораль часто выражена имплицитно: читатель восстанавливает авторскую идею по исходу краткого сюжета.`,
    },
    160: {
      question: `Выполните орфографический и пунктуационный практикум: восстановите текст К. Г. Паустовского о приметах.`,
      answer: `Примет так много, что о них можно было бы написать целую книгу. В городах приметы нам не нужны. Огненную рябину заменяет эмалированная синяя табличка с названием улицы. Время узнаётся не по высоте солнца, не по положению созвездий и даже не по петушиным крикам, а по часам. Предсказания погоды передаются по радио. В городах большинство наших природных инстинктов погружается в спячку. Но стоит провести две-три ночи в лесу — и снова обостряется слух, зорче делается глаз, тоньше обоняние.\nПриметы связаны со всем: с цветом неба, с росой и туманами, с окриком птиц и яркостью звёздного света.`,
      rule: `Перед придаточным с «что» ставится запятая; в конструкции «не..., не..., а...» однородные члены разделяются запятыми; «две-три» пишется через дефис.`,
    },
    161: {
      question: `Раскройте значение ключевых слов раздела «Речь. Текст» и объясните эпиграф Л. В. Щербы о литературном языке.`,
      answer: `Реклама — сообщение, привлекающее внимание к товару, услуге или идее; объявление — краткое публичное сообщение; заголовок — название текста; абзац — композиционно-смысловая часть текста. Комплимент — доброжелательная похвала; автобиография — рассказ автора о собственной жизни; воспоминания — рассказ о прошлом; беседа — диалог на определённую тему; спор — обсуждение при расхождении мнений; путевые заметки — записи о путешествии.\nПублицистический стиль сообщает общественно важные сведения и воздействует на читателя; язык художественной литературы создаёт образы эстетическими средствами; притча — краткий поучительный иносказательный рассказ; метафора — перенос значения по сходству. Фактуальная информация сообщает факты; подтекстовая подразумевается и восстанавливается читателем; концептуальная выражает основную авторскую идею и оценку.\nЭпиграф Щербы означает, что литературный язык — общее культурное наследие поколений. Благодаря его точным и богатым средствам мы выражаем собственные мысли и чувства и одновременно понимаем тексты людей прошлых эпох. Сохранение нормы не мешает развитию языка, а обеспечивает связь времени и культуры.`,
      rule: `Ключевые понятия раздела связывают строение текста, жанры, стили, выразительные средства и уровни передаваемой информации.`,
    }
  });

  const tasks = course.flatMap(chapter => chapter.tasks || []);
  for (const task of tasks) {
    const item = solutions[Number(task.key)];
    if (!item) continue;
    task.question = item.question;
    task.answer = item.answer;
    task.rule = item.rule;
    task.steps = [
      'Прочитали все пункты условия и разделили их на отдельные действия.',
      'Сопоставили слова и примеры с правилом и историко-языковым контекстом.',
      'Записали готовый ответ в том же порядке, в каком заданы вопросы.'
    ];
    task.summaryOnly = false;
    task.answerPending = false;
  }
})();
